#ifdef SUPPORT_ASSIST_UI_SELFCHECK
// Replace identifying values in anything the screenshot harness is about to draw.
//
// Built ONLY for the screenshot harness. The shipped product must never do this: an engineer
// reading a path needs the real one, and a tool that quietly rewrites evidence is worse than one
// that shows an awkward truth. The figures in the user guides are published, though, and they
// should not carry the account name, machine name or profile directory of whoever captured them.
//
// Longest first, so "C:\Users\name" is rewritten before the bare "name" inside it.
// The names in SAT_UI_REDACT_NAMES, separated by commas, letters only.
const std::vector<std::wstring>& selfcheck_names_to_redact() {
  static const std::vector<std::wstring> names = [] {
    std::vector<std::wstring> found;
    wchar_t buffer[1024]{};
    const DWORD length = GetEnvironmentVariableW(L"SAT_UI_REDACT_NAMES", buffer, static_cast<DWORD>(std::size(buffer)));
    std::wstring name;
    const auto flush = [&]() {
      if (name.size() >= 2U)
        found.push_back(name);
      name.clear();
    };
    for (DWORD index = 0; index < length && index < std::size(buffer); ++index) {
      if (buffer[index] == L',')
        flush();
      else if (::iswalpha(buffer[index]))
        name.push_back(buffer[index]);
    }
    flush();
    return found;
  }();
  return names;
}

const std::vector<std::pair<std::wstring, std::wstring>>& selfcheck_redactions() {
  static const std::vector<std::pair<std::wstring, std::wstring>> table = [] {
    std::vector<std::pair<std::wstring, std::wstring>> entries;

    wchar_t user[256]{};
    DWORD user_length = static_cast<DWORD>(std::size(user));
    std::wstring account;
    if (GetUserNameW(user, &user_length) != FALSE && user_length > 1)
      account.assign(user, user_length - 1);

    wchar_t machine[MAX_COMPUTERNAME_LENGTH + 1]{};
    DWORD machine_length = static_cast<DWORD>(std::size(machine));
    std::wstring computer;
    if (GetComputerNameW(machine, &machine_length) != FALSE)
      computer.assign(machine, machine_length);

    if (!account.empty()) {
      wchar_t profile[MAX_PATH]{};
      DWORD profile_length = static_cast<DWORD>(std::size(profile));
      if (GetEnvironmentVariableW(L"USERPROFILE", profile, profile_length) != 0)
        entries.emplace_back(profile, L"C:\\Users\\USER");
      entries.emplace_back(L"C:\\Users\\" + account, L"C:\\Users\\USER");
      // The machine name stays; only the account after it changes.
      if (!computer.empty())
        entries.emplace_back(computer + L"\\" + account, computer + L"\\USER");
      entries.emplace_back(account, L"USER");
    }
    // Further names to hide, such as those in evidence collected on other machines: SAT_UI_REDACT_NAMES,
    // separated by commas. A name of three letters or fewer is matched as a whole word (see below).
    for (const std::wstring& name : selfcheck_names_to_redact())
      if (name.size() > 3U)
        entries.emplace_back(name, L"USER");

    std::stable_sort(entries.begin(), entries.end(),
                     [](const auto& left, const auto& right) {
                       return left.first.size() > right.first.size();
                     });
    return entries;
  }();
  return table;
}

std::wstring selfcheck_redact(std::wstring_view value) {
  std::wstring text(value);
  for (const auto& [needle, replacement] : selfcheck_redactions()) {
    if (needle.empty())
      continue;
    // Case-insensitive: a path may carry the account name in any case, and "Name" and "name" are the
    // same account.
    std::wstring folded_text;
    std::wstring folded_needle;
    folded_text.reserve(text.size());
    for (wchar_t character : text)
      folded_text.push_back(static_cast<wchar_t>(::towlower(character)));
    for (wchar_t character : needle)
      folded_needle.push_back(static_cast<wchar_t>(::towlower(character)));

    std::size_t at = folded_text.find(folded_needle);
    while (at != std::wstring::npos) {
      text.replace(at, needle.size(), replacement);
      folded_text.replace(at, needle.size(), replacement);
      for (std::size_t index = at; index < at + replacement.size(); ++index)
        folded_text[index] = static_cast<wchar_t>(::towlower(folded_text[index]));
      at = folded_text.find(folded_needle, at + replacement.size());
    }
  }
  // A short name as a word only, so a longer word that starts with it stays. Each pattern is built once,
  // and a text without the name is not searched: thousands of rows pass through here.
  static const std::vector<std::pair<std::wstring, std::wregex>> short_names = [] {
    std::vector<std::pair<std::wstring, std::wregex>> built;
    for (const std::wstring& name : selfcheck_names_to_redact())
      if (name.size() <= 3U)
        built.emplace_back(name, std::wregex(L"\\b" + name + L"\\b"));
    return built;
  }();
  for (const auto& [name, pattern] : short_names) {
    if (text.find(name) != std::wstring::npos)
      text = std::regex_replace(text, pattern, L"USER");
  }
  return text;
}

// Redact tree item text on its way in. Several call sites build their own TVINSERTSTRUCTW, so the
// substitution happens here rather than being repeated - and missed - at each one.
HTREEITEM selfcheck_insert_tree_item(HWND tree, TVINSERTSTRUCTW* item) {
  std::wstring redacted;
  if (item != nullptr && (item->item.mask & TVIF_TEXT) != 0 && item->item.pszText != nullptr &&
      item->item.pszText != LPSTR_TEXTCALLBACKW) {
    redacted = selfcheck_redact(item->item.pszText);
    item->item.pszText = redacted.data();
  }
  return TreeView_InsertItem(tree, item);
}
#endif

// Adds an item to a combo box filled from evidence (machine, job, run and session names). Under
// the self-check the text is redacted like every other control's.
LRESULT add_combo_item(HWND combo, std::wstring_view text) {
#ifdef SUPPORT_ASSIST_UI_SELFCHECK
  const std::wstring shown = selfcheck_redact(text);
#else
  const std::wstring shown(text);
#endif
  return SendMessageW(combo, CB_ADDSTRING, 0, reinterpret_cast<LPARAM>(shown.c_str()));
}

// A table row's cells on their way into a list view, redacted under the self-check like the
// combo items above; unchanged otherwise.
template <typename Cells>
void redact_cells(Cells& cells) {
#ifdef SUPPORT_ASSIST_UI_SELFCHECK
  for (auto& cell : cells)
    cell = selfcheck_redact(cell);
#else
  static_cast<void>(cells);
#endif
}

