// The Remote Port Checker's rows (gui_shared/connectivity_rows.hpp) as results grid rows.
std::vector<std::array<std::wstring, 4>> wide_rows(const std::vector<support_assist::gui::ConnectivityRow>& rows) {
  std::vector<std::array<std::wstring, 4>> converted;
  converted.reserve(rows.size());
  for (const auto& row : rows)
    converted.push_back({wide(row.kind), wide(row.target), wide(row.detail), wide(row.state)});
  return converted;
}

enum class ExplicitLoopbackTarget {
  none,
  hostname,
  ipv4,
  ipv6,
};

ExplicitLoopbackTarget classify_explicit_loopback_target(std::string_view value) {
  std::string text(value);
  while (!text.empty() && std::isspace(static_cast<unsigned char>(text.front())) != 0)
    text.erase(text.begin());
  while (!text.empty() && std::isspace(static_cast<unsigned char>(text.back())) != 0)
    text.pop_back();
  std::transform(text.begin(), text.end(), text.begin(), [](unsigned char ch) {
    return static_cast<char>(std::tolower(ch));
  });
  if (text.size() >= 2U && text.front() == '[' && text.back() == ']')
    text = text.substr(1, text.size() - 2U);
  if (text == "localhost" || text == "localhost.")
    return ExplicitLoopbackTarget::hostname;
  if (text.rfind("127.", 0) == 0)
    return ExplicitLoopbackTarget::ipv4;
  if (text == "::1" || text == "0:0:0:0:0:0:0:1")
    return ExplicitLoopbackTarget::ipv6;
  return ExplicitLoopbackTarget::none;
}

