std::wstring product_for_review_machine(const support_assist::VeeamLogReviewResult& review,
                                        const support_assist::VeeamMachineRecord* machine) {
  if (machine == nullptr)
    return wide(review.product_type.empty() ? "Product not identified" : review.product_type);
  std::string product;
  for (const auto& bundle : review.bundles) {
    if (bundle.primary_machine_key == machine->key && !bundle.product_type.empty()) {
      product = bundle.product_type;
      if (bundle.product_confidence == support_assist::ParserConfidence::verified)
        break;
    }
  }
  return product_name_for_machine_role(machine->role,
                                       product.empty() ? review.product_type : product);
}

