void set_list_sort_indicator(HWND list, int column, bool ascending) {
  if (list == nullptr)
    return;
  HWND header = ListView_GetHeader(list);
  if (header == nullptr)
    return;
  const int count = Header_GetItemCount(header);
  for (int index = 0; index < count; ++index) {
    HDITEMW item{};
    item.mask = HDI_FORMAT;
    if (Header_GetItem(header, index, &item) == FALSE)
      continue;
    item.fmt &= ~(HDF_SORTUP | HDF_SORTDOWN);
    if (index == column)
      item.fmt |= ascending ? HDF_SORTUP : HDF_SORTDOWN;
    Header_SetItem(header, index, &item);
  }
}

void sort_plain_list_view(HWND list, int column) {
  if (list == nullptr || column < 0)
    return;
  HWND header = ListView_GetHeader(list);
  const int columns = header == nullptr ? 0 : Header_GetItemCount(header);
  if (column >= columns)
    return;
  HDITEMW header_item{};
  header_item.mask = HDI_FORMAT;
  Header_GetItem(header, column, &header_item);
  const bool ascending = (header_item.fmt & HDF_SORTUP) == 0;
  struct PlainRow { std::vector<std::wstring> cells; };
  std::vector<PlainRow> rows;
  const int count = ListView_GetItemCount(list);
  rows.reserve(static_cast<std::size_t>(std::max(0, count)));
  for (int row = 0; row < count; ++row) {
    PlainRow value;
    value.cells.resize(static_cast<std::size_t>(columns));
    for (int col = 0; col < columns; ++col) {
      wchar_t text[4096]{};
      ListView_GetItemText(list, row, col, text, static_cast<int>(std::size(text)));
      value.cells[static_cast<std::size_t>(col)] = text;
    }
    rows.push_back(std::move(value));
  }
  const auto folded = [](std::wstring value) {
    std::transform(value.begin(), value.end(), value.begin(), [](wchar_t ch) {
      return static_cast<wchar_t>(std::towlower(ch));
    });
    return value;
  };
  std::stable_sort(rows.begin(), rows.end(), [&](const auto& left, const auto& right) {
    const auto left_text = folded(left.cells[static_cast<std::size_t>(column)]);
    const auto right_text = folded(right.cells[static_cast<std::size_t>(column)]);
    if (left_text == right_text)
      return left.cells.front() < right.cells.front();
    return ascending ? left_text < right_text : left_text > right_text;
  });
  ListView_DeleteAllItems(list);
  for (std::size_t row = 0; row < rows.size(); ++row) {
    auto cells = rows[row].cells;
    LVITEMW item{};
    item.mask = LVIF_TEXT;
    item.iItem = static_cast<int>(row);
    item.pszText = cells[0].data();
    const int inserted = ListView_InsertItem(list, &item);
    for (int col = 1; inserted >= 0 && col < columns; ++col)
      ListView_SetItemText(list, inserted, col, cells[static_cast<std::size_t>(col)].data());
  }
  set_list_sort_indicator(list, column, ascending);
}

int severity_sort_rank(std::wstring_view value) {
  std::wstring folded(value);
  std::transform(folded.begin(), folded.end(), folded.begin(), [](wchar_t ch) {
    return static_cast<wchar_t>(std::towlower(ch));
  });
  if (folded.find(L"critical") != std::wstring::npos || folded.find(L"error") != std::wstring::npos)
    return 0;
  if (folded.find(L"warning") != std::wstring::npos)
    return 1;
  if (folded.find(L"info") != std::wstring::npos)
    return 2;
  return 3;
}

std::wstring parser_confidence_label(support_assist::ParserConfidence confidence) {
  switch (confidence) {
  case support_assist::ParserConfidence::verified:
    return L"Verified";
  case support_assist::ParserConfidence::probable:
    return L"Inferred";
  case support_assist::ParserConfidence::unconfirmed:
    return L"Not verified";
  }
  return L"Not verified";
}

