std::vector<std::string> split_report_lines(std::string_view text) {
  std::vector<std::string> lines;
  std::size_t start = 0;
  while (start <= text.size()) {
    const std::size_t end = text.find('\n', start);
    std::string line(text.substr(start, end == std::string_view::npos ? text.size() - start : end - start));
    if (!line.empty() && line.back() == '\r')
      line.pop_back();
    lines.push_back(std::move(line));
    if (end == std::string_view::npos)
      break;
    start = end + 1U;
  }
  return lines;
}


// The case topology and work-item model, shared with the Linux edition.
using envreview::CaseTopologyEntity;
