const CaseTopologyEntity* selected_case_topology_entity(HWND combo,
                                                        const support_assist::VeeamLogReviewResult& review,
                                                        std::vector<CaseTopologyEntity>& storage) {
  storage = build_case_topology_entities(review);
  const LRESULT selected = SendMessageW(combo, CB_GETCURSEL, 0, 0);
  if (selected == CB_ERR)
    return nullptr;
  const LRESULT data = SendMessageW(combo, CB_GETITEMDATA, static_cast<WPARAM>(selected), 0);
  if (data < 0 || static_cast<std::size_t>(data) >= storage.size())
    return nullptr;
  return &storage[static_cast<std::size_t>(data)];
}

