// A "Filter rows" box, as the one above the results table.
HWND create_filter_box(HWND parent, HINSTANCE instance, int identifier, HFONT font) {
  HWND box = CreateWindowExW(WS_EX_CLIENTEDGE, WC_EDITW, L"", WS_CHILD | WS_TABSTOP | ES_AUTOHSCROLL,
                             0, 0, 0, 0, parent,
                             reinterpret_cast<HMENU>(static_cast<INT_PTR>(identifier)), instance,
                             nullptr);
  SendMessageW(box, EM_SETCUEBANNER, TRUE, reinterpret_cast<LPARAM>(L"Filter rows"));
  SendMessageW(box, WM_SETFONT, reinterpret_cast<WPARAM>(font), TRUE);
  return box;
}

// What a filter box holds, without the blanks around it.
std::wstring filter_box_text(HWND box) {
  const int length = GetWindowTextLengthW(box);
  std::wstring typed(static_cast<std::size_t>(length) + 1U, L'\0');
  GetWindowTextW(box, typed.data(), length + 1);
  typed.resize(static_cast<std::size_t>(length));
  const auto blank = [](wchar_t value) { return value == L' ' || value == L'\t'; };
  while (!typed.empty() && blank(typed.back()))
    typed.pop_back();
  while (!typed.empty() && blank(typed.front()))
    typed.erase(typed.begin());
  return typed;
}

// Every filter box keeps a row when one of its cells contains the typed text, ignoring case.
template <typename Cells>
bool row_contains(const Cells& cells, const std::wstring& typed) {
  if (typed.empty())
    return true;
  const auto folded = [](std::wstring_view value) {
    std::wstring text(value);
    std::transform(text.begin(), text.end(), text.begin(),
                   [](wchar_t character) { return static_cast<wchar_t>(std::towlower(character)); });
    return text;
  };
  const std::wstring needle = folded(typed);
  for (const auto& cell : cells) {
    if (folded(cell).find(needle) != std::wstring::npos)
      return true;
  }
  return false;
}

bool is_veeam_review_mode(int mode) noexcept {
  return mode >= 1 && mode <= 6;
}

support_assist::VeeamReviewProfile review_profile_for_mode(int mode) noexcept {
  switch (mode) {
  case 1:
    return support_assist::VeeamReviewProfile::vaw;
  case 2:
    return support_assist::VeeamReviewProfile::vbr;
  case 3:
    return support_assist::VeeamReviewProfile::sql_plugin;
  case 4:
    return support_assist::VeeamReviewProfile::rman_plugin;
  case 5:
    return support_assist::VeeamReviewProfile::automatic;
  case 6:
    return support_assist::VeeamReviewProfile::generic;
  default:
    return support_assist::VeeamReviewProfile::automatic;
  }
}

int mode_for_review_profile(support_assist::VeeamReviewProfile profile) noexcept {
  switch (profile) {
  case support_assist::VeeamReviewProfile::vaw:
    return 1;
  case support_assist::VeeamReviewProfile::vbr:
    return 2;
  case support_assist::VeeamReviewProfile::sql_plugin:
    return 3;
  case support_assist::VeeamReviewProfile::rman_plugin:
    return 4;
  case support_assist::VeeamReviewProfile::automatic:
    return 5;
  case support_assist::VeeamReviewProfile::generic:
    return 6;
  }
  return 5;
}

std::string profile_name_for_product(std::string_view product) {
  const std::string folded = support_assist::ascii_lower(product);
  if (folded.find("backup & replication") != std::string::npos) return "vbr";
  if (folded.find("microsoft sql") != std::string::npos) return "sql-plugin";
  if (folded.find("oracle rman") != std::string::npos) return "rman-plugin";
  if (folded.find("agent for microsoft windows") != std::string::npos) return "vaw";
  // VAL currently uses Auto/Generic parsing in 0.4. Product identity is still
  // retained accurately; a dedicated VAL parser remains part of the 0.5 parser overhaul.
  if (folded.find("agent for linux") != std::string::npos) return "automatic";
  return "automatic";
}

std::optional<support_assist::VeeamReviewProfile> choose_review_profile(HWND owner) {
  HMENU menu = CreatePopupMenu();
  AppendMenuW(menu, MF_STRING, 1, L"Auto Detect (recommended)");
  AppendMenuW(menu, MF_SEPARATOR, 0, nullptr);
  AppendMenuW(menu, MF_STRING, 2, L"Veeam Agent for Microsoft Windows (VAW)");
  AppendMenuW(menu, MF_STRING, 3, L"Veeam Backup & Replication (VBR)");
  AppendMenuW(menu, MF_STRING, 4, L"Veeam Plug-in for Microsoft SQL Server");
  AppendMenuW(menu, MF_STRING, 5, L"Veeam Plug-in for Oracle RMAN");
  AppendMenuW(menu, MF_STRING, 6, L"Generic Veeam logs");
  POINT point{};
  GetCursorPos(&point);
  const UINT selected = TrackPopupMenu(menu, TPM_RETURNCMD | TPM_LEFTALIGN | TPM_TOPALIGN,
                                       point.x, point.y, 0, owner, nullptr);
  DestroyMenu(menu);
  switch (selected) {
  case 1: return support_assist::VeeamReviewProfile::automatic;
  case 2: return support_assist::VeeamReviewProfile::vaw;
  case 3: return support_assist::VeeamReviewProfile::vbr;
  case 4: return support_assist::VeeamReviewProfile::sql_plugin;
  case 5: return support_assist::VeeamReviewProfile::rman_plugin;
  case 6: return support_assist::VeeamReviewProfile::generic;
  default: return std::nullopt;
  }
}

std::vector<std::string> split_values(std::wstring_view value) {
  std::vector<std::string> output;
  std::size_t start = 0;
  while (start < value.size()) {
    const std::size_t end = value.find_first_of(L";,\r\n", start);
    std::wstring_view item =
        value.substr(start, end == std::wstring_view::npos ? value.size() - start : end - start);
    while (!item.empty() && iswspace(item.front()))
      item.remove_prefix(1);
    while (!item.empty() && iswspace(item.back()))
      item.remove_suffix(1);
    if (!item.empty())
      output.push_back(narrow(item));
    if (end == std::wstring_view::npos)
      break;
    start = end + 1U;
  }
  return output;
}

std::vector<std::wstring> split_wide(std::wstring_view value, wchar_t delimiter) {
  std::vector<std::wstring> output;
  std::size_t start = 0;
  while (start <= value.size()) {
    const std::size_t end = value.find(delimiter, start);
    std::wstring item(
        value.substr(start, end == std::wstring_view::npos ? value.size() - start : end - start));
    while (!item.empty() && iswspace(item.front()))
      item.erase(item.begin());
    while (!item.empty() && iswspace(item.back()))
      item.pop_back();
    output.push_back(std::move(item));
    if (end == std::wstring_view::npos)
      break;
    start = end + 1U;
  }
  return output;
}

template <typename Integer> std::optional<Integer> parse_number(std::wstring_view text) {
  const std::string value = narrow(text);
  Integer output{};
  const auto [position, error] = std::from_chars(value.data(), value.data() + value.size(), output);
  if (error != std::errc{} || position != value.data() + value.size())
    return std::nullopt;
  return output;
}


std::optional<support_assist::DateOrder> parse_date_order_label(std::wstring_view text) {
  std::wstring folded(text);
  std::transform(folded.begin(), folded.end(), folded.begin(), [](wchar_t character) {
    return static_cast<wchar_t>(std::towlower(character));
  });
  while (!folded.empty() && iswspace(folded.front()))
    folded.erase(folded.begin());
  while (!folded.empty() && iswspace(folded.back()))
    folded.pop_back();
  if (folded.empty() || folded == L"auto" || folded == L"automatic")
    return support_assist::DateOrder::automatic;
  if (folded == L"mdy" || folded == L"month/day/year")
    return support_assist::DateOrder::month_day_year;
  if (folded == L"dmy" || folded == L"day/month/year")
    return support_assist::DateOrder::day_month_year;
  if (folded == L"locale" || folded == L"system")
    return support_assist::DateOrder::system_locale;
  if (folded == L"iso" || folded == L"iso-only")
    return support_assist::DateOrder::iso_only;
  return std::nullopt;
}

