std::wstring folded_wide(std::wstring_view value) {
  std::wstring output(value);
  std::transform(output.begin(), output.end(), output.begin(), [](wchar_t character) {
    return static_cast<wchar_t>(std::towlower(character));
  });
  return output;
}

std::wstring detected_product_registry_version(
    const support_assist::DetectedProduct& detected,
    const std::vector<InstalledProductEntry>& installed_products) {
  const std::wstring definition_name = folded_wide(wide(detected.definition.display_name));
  for (const auto& installed : installed_products) {
    const std::wstring installed_name = folded_wide(installed.name);
    const bool excluded = std::any_of(
        detected.definition.installed_product_name_exclusion_tokens.begin(),
        detected.definition.installed_product_name_exclusion_tokens.end(),
        [&](const std::string& token) {
          const std::wstring folded_token = folded_wide(wide(token));
          return !folded_token.empty() && installed_name.find(folded_token) != std::wstring::npos;
        });
    if (excluded)
      continue;

    bool matched = false;
    if (!detected.definition.installed_product_name_tokens.empty()) {
      matched = std::any_of(
          detected.definition.installed_product_name_tokens.begin(),
          detected.definition.installed_product_name_tokens.end(),
          [&](const std::string& token) {
            const std::wstring folded_token = folded_wide(wide(token));
            return !folded_token.empty() && installed_name.find(folded_token) != std::wstring::npos;
          });
    } else if (!definition_name.empty()) {
      matched = installed_name == definition_name ||
                installed_name.find(definition_name) != std::wstring::npos;
    }

    if (matched && !installed.version.empty())
      return installed.version;
  }
  return {};
}

void draw_review_bookmark_glyph(HDC dc, const RECT& row_rect, bool filled) {
  if (dc == nullptr)
    return;
  const int width = 10;
  const int height = 14;
  const int left = row_rect.left + 7;
  const int top = row_rect.top + std::max(1L, (row_rect.bottom - row_rect.top - height) / 2L);
  POINT points[5]{
      {left, top},
      {left + width, top},
      {left + width, top + height},
      {left + width / 2, top + height - 4},
      {left, top + height}};

  const COLORREF color = filled ? themed(RGB(101, 205, 175)) : themed(RGB(157, 177, 171));
  HPEN pen = CreatePen(PS_SOLID, 1, color);
  HBRUSH brush = filled ? CreateSolidBrush(color)
                        : static_cast<HBRUSH>(GetStockObject(HOLLOW_BRUSH));
  const HGDIOBJ old_pen = SelectObject(dc, pen);
  const HGDIOBJ old_brush = SelectObject(dc, brush);
  Polygon(dc, points, static_cast<int>(std::size(points)));
  SelectObject(dc, old_brush);
  SelectObject(dc, old_pen);
  if (filled)
    DeleteObject(brush);
  DeleteObject(pen);
}

void draw_dashboard_metric_card(const DRAWITEMSTRUCT& draw,
                                std::wstring_view title,
                                std::wstring_view value,
                                std::wstring_view detail,
                                support_assist::HealthSeverity severity,
                                HFONT small_font,
                                HFONT value_font) {
  COLORREF background = themed(RGB(18, 48, 49));
  COLORREF border_color = themed(RGB(43, 86, 78));
  COLORREF value_color = themed(RGB(229, 241, 236));
  switch (severity) {
  case support_assist::HealthSeverity::critical:
    background = themed(RGB(61, 29, 31));
    border_color = themed(RGB(196, 76, 82));
    value_color = themed(RGB(255, 133, 133));
    break;
  case support_assist::HealthSeverity::warning:
    background = themed(RGB(59, 45, 27));
    border_color = themed(RGB(191, 137, 52));
    value_color = themed(RGB(255, 190, 91));
    break;
  case support_assist::HealthSeverity::informational:
    background = themed(RGB(22, 49, 54));
    border_color = themed(RGB(59, 125, 134));
    value_color = themed(RGB(146, 219, 224));
    break;
  case support_assist::HealthSeverity::healthy:
    background = themed(RGB(18, 48, 43));
    border_color = themed(RGB(57, 135, 88));
    value_color = themed(RGB(151, 231, 169));
    break;
  case support_assist::HealthSeverity::unknown:
  default:
    background = themed(RGB(38, 44, 45));
    border_color = themed(RGB(91, 102, 104));
    value_color = themed(RGB(196, 202, 203));
    break;
  }

  HBRUSH fill = CreateSolidBrush(background);
  HPEN border = CreatePen(PS_SOLID, 1, border_color);
  const HGDIOBJ old_brush = SelectObject(draw.hDC, fill);
  const HGDIOBJ old_pen = SelectObject(draw.hDC, border);
  RoundRect(draw.hDC,
            draw.rcItem.left + 1,
            draw.rcItem.top + 1,
            draw.rcItem.right - 1,
            draw.rcItem.bottom - 1,
            10,
            10);

  RECT severity_bar{draw.rcItem.left + 2, draw.rcItem.top + 7,
                    draw.rcItem.left + 6, draw.rcItem.bottom - 7};
  HBRUSH severity_brush = CreateSolidBrush(border_color);
  FillRect(draw.hDC, &severity_bar, severity_brush);
  DeleteObject(severity_brush);

  SetBkMode(draw.hDC, TRANSPARENT);
  RECT title_rect{draw.rcItem.left + 14, draw.rcItem.top + 8,
                  draw.rcItem.right - 12, draw.rcItem.top + 28};
  SelectObject(draw.hDC, small_font);
  SetTextColor(draw.hDC, themed(RGB(183, 204, 196)));
#ifdef SUPPORT_ASSIST_UI_SELFCHECK
  const std::wstring title_text = selfcheck_redact(title);
#else
  const std::wstring title_text(title);
#endif
  DrawTextW(draw.hDC, title_text.c_str(), -1, &title_rect,
            DT_LEFT | DT_SINGLELINE | DT_END_ELLIPSIS | DT_NOPREFIX);

  RECT value_rect{draw.rcItem.left + 14, draw.rcItem.top + 29,
                  draw.rcItem.right - 12, draw.rcItem.top + 60};
  SelectObject(draw.hDC, value_font);
  SetTextColor(draw.hDC, value_color);
#ifdef SUPPORT_ASSIST_UI_SELFCHECK
  const std::wstring value_text = selfcheck_redact(value);
#else
  const std::wstring value_text(value);
#endif
  DrawTextW(draw.hDC, value_text.c_str(), -1, &value_rect,
            DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS | DT_NOPREFIX);

  RECT detail_rect{draw.rcItem.left + 14, draw.rcItem.top + 62,
                   draw.rcItem.right - 12, draw.rcItem.bottom - 7};
  SelectObject(draw.hDC, small_font);
  SetTextColor(draw.hDC, themed(RGB(176, 196, 188)));
#ifdef SUPPORT_ASSIST_UI_SELFCHECK
  const std::wstring detail_text = selfcheck_redact(detail);
#else
  const std::wstring detail_text(detail);
#endif
  // DT_EDITCONTROL draws whole lines only, and DT_END_ELLIPSIS ends the last one that fits with an
  // ellipsis, so a detail longer than the card never shows half a line cut through the middle.
  DrawTextW(draw.hDC, detail_text.c_str(), -1, &detail_rect,
            DT_LEFT | DT_WORDBREAK | DT_EDITCONTROL | DT_END_ELLIPSIS | DT_NOPREFIX);

  SelectObject(draw.hDC, old_brush);
  SelectObject(draw.hDC, old_pen);
  DeleteObject(fill);
  DeleteObject(border);
}

void add_viewer_style(SourceViewerState& state,
                      int line_start,
                      std::size_t local_start,
                      std::size_t length,
                      COLORREF foreground,
                      bool bold = false,
                      COLORREF background = CLR_INVALID,
                      bool italic = false,
                      bool underline = false) {
  if (length == 0U)
    return;
  const auto absolute_start = line_start + static_cast<int>(local_start);
  state.styles.push_back(ViewerStyleRange{absolute_start,
                                          absolute_start + static_cast<int>(length),
                                          foreground,
                                          background,
                                          bold,
                                          italic,
                                          underline});
}

// A stable colour for one identifier value.
//
// Following a single session, thread or host through a log means finding the same value again
// further down, and in a Veeam log there are dozens of near-identical GUIDs on screen at once.
// Giving every distinct value its own colour turns that from reading hex digit by digit into
// spotting a colour. The colour is derived from the text, so the same GUID is the same colour
// every time the file is opened, and two different GUIDs are almost never the same colour.
//
// The palette is chosen to sit apart from the severity colours: nothing here should be mistakable
// for an error or a warning.
COLORREF identifier_color(std::wstring_view value) {
  static constexpr COLORREF palette[] = {
      RGB(0x7F, 0xB3, 0xD5), RGB(0x76, 0xD7, 0xC4), RGB(0xF7, 0xDC, 0x6F),
      RGB(0xBB, 0x8F, 0xCE), RGB(0x85, 0xC1, 0xE9), RGB(0xF0, 0xB2, 0x7A),
      RGB(0x82, 0xE0, 0xAA), RGB(0xD7, 0xBD, 0xE2), RGB(0xA3, 0xE4, 0xD7),
      RGB(0xF9, 0xE7, 0x9F), RGB(0xAE, 0xD6, 0xF1), RGB(0xE6, 0xB0, 0xAA)};
  std::uint32_t hash = 2166136261U;  // FNV-1a
  for (const wchar_t character : value) {
    // Only the identifier itself contributes. The same thread appears as "<  8592>" in the prefix
    // column and as "8592" in "thread id: 8592"; a GUID appears braced in one line and bare in the
    // next. Ignoring punctuation and case is what makes those render as the SAME colour, which is
    // the whole reason for colouring them.
    if (std::iswalnum(static_cast<wint_t>(character)) == 0)
      continue;
    const wchar_t folded = (character >= L'A' && character <= L'Z')
                               ? static_cast<wchar_t>(character - L'A' + L'a')
                               : character;
    hash ^= static_cast<std::uint32_t>(folded);
    hash *= 16777619U;
  }
  return palette[hash % (sizeof(palette) / sizeof(palette[0]))];
}

void color_semantic_log_line(SourceViewerState& state,
                             std::wstring_view raw_line,
                             std::wstring_view rendered_line,
                             std::size_t prefix_length,
                             int line_start,
                             bool selected) {
  // Palette and structure follow a Notepad++ user defined language used to read these same
  // logs. The important part is structural, not chromatic: the ground stays uniform and
  // only the FOREGROUND carries meaning. The previous model washed whole rows in red and amber
  // backgrounds, which turned a page of ordinary retries into a wall of colour and made the lines
  // that matter no easier to find than the ones that did not.
  constexpr COLORREF ground = RGB(0x3F, 0x3F, 0x3F);
  constexpr COLORREF ground_selected = RGB(0x4E, 0x4E, 0x4E);
  constexpr COLORREF text = RGB(0xDC, 0xDC, 0xCC);        // DEFAULT
  constexpr COLORREF muted = RGB(0x8A, 0x8F, 0x8A);
  constexpr COLORREF structural = RGB(0xDF, 0xC4, 0x7D);  // OPERATORS
  constexpr COLORREF metadata = RGB(0xE3, 0xCE, 0xAB);    // KEYWORDS3/5
  constexpr COLORREF link = RGB(0xED, 0xD6, 0xED);        // KEYWORDS1
  constexpr COLORREF success = RGB(0x00, 0xFF, 0x40);     // KEYWORDS4
  constexpr COLORREF warn = RGB(0xFF, 0x80, 0x00);        // KEYWORDS6
  constexpr COLORREF error = RGB(0xFF, 0x00, 0x00);       // KEYWORDS7
  constexpr COLORREF banner = RGB(0xFF, 0x80, 0x40);      // KEYWORDS2 / LINE COMMENTS
  // A whole error line in pure FF0000 is unreadable at length, so the severity TOKEN takes the
  // strong colour and the message body takes a legible tint of it.
  constexpr COLORREF error_body = RGB(0xF0, 0x9C, 0x9C);
  constexpr COLORREF warn_body = RGB(0xE8, 0xC4, 0x89);

  const support_assist::LogLineHighlight analysis =
      support_assist::analyze_veeam_log_line(raw_line);

  COLORREF row_text = text;
  const COLORREF row_background = selected ? ground_selected : ground;
  switch (analysis.severity) {
  case support_assist::LogLineSeverity::critical:
  case support_assist::LogLineSeverity::error:
    row_text = error_body;
    break;
  case support_assist::LogLineSeverity::warning:
    row_text = warn_body;
    break;
  case support_assist::LogLineSeverity::information:
  case support_assist::LogLineSeverity::unknown:
    // Routine body text sits one step back from the errors and warnings around it. This is the
    // "important vs not" contrast: nothing is hidden, but the eye is not asked to weigh every
    // line equally.
    if (!analysis.heading)
      row_text = RGB(0xC3, 0xC6, 0xBE);
    break;
  }

  // Remember where the errors and warnings are so "next issue" is a lookup rather than a re-scan.
  // Stack continuations are excluded deliberately: 692 identical frames under one exception are one
  // issue, and stopping on each of them is not navigation.
  if ((analysis.severity == support_assist::LogLineSeverity::error ||
       analysis.severity == support_assist::LogLineSeverity::critical ||
       analysis.severity == support_assist::LogLineSeverity::warning) &&
      !analysis.stack_continuation) {
    state.notable_offsets.push_back(line_start);
  }

  add_viewer_style(state, line_start, 0, rendered_line.size(), row_text, false,
                   row_background, analysis.stack_continuation);
  add_viewer_style(state, line_start, 0, std::min(prefix_length, rendered_line.size()),
                   selected ? RGB(205, 205, 205) : muted, selected);

  const bool error_row = analysis.severity == support_assist::LogLineSeverity::error ||
                         analysis.severity == support_assist::LogLineSeverity::critical;
  for (const auto& span : analysis.spans) {
    if (span.start >= raw_line.size())
      continue;
    const std::size_t length = std::min(span.length, raw_line.size() - span.start);

    // IMPORTANCE GATE.
    //
    // The reference is a Notepad++ user defined language used to read these logs,
    // and the thing that makes it readable is not its palette - it is its RESTRAINT. It leaves the
    // overwhelming majority of a line plain and lights up only what changes the reading: a
    // severity token, a session banner. SAT was colouring the timestamp, the thread id, the
    // component, every GUID, every path and every IP address on EVERY line, including thousands of
    // routine Info lines, which produces a page where nothing stands out because everything does.
    //
    // So: on a routine line only structure that helps you SKIM survives. On a line that already
    // matters - error, warning, or a session boundary - the full vocabulary is allowed, because
    // there the detail is what the engineer has stopped to read.
    const bool notable_line = error_row ||
                              analysis.severity == support_assist::LogLineSeverity::warning ||
                              analysis.heading;
    if (!notable_line) {
      // Identifiers stay coloured on EVERY line, routine or not.
      //
      // The first pass of this gate treated a GUID and an IP address as decoration and dropped them
      // on Info lines, which is most of a Veeam log - so the values an engineer actually navigates
      // by were the ones left uncoloured. They are not emphasis: each carries a stable per-value
      // colour, so they help you find the next occurrence rather than shout.
      const bool skimmable = span.kind == support_assist::LogHighlightKind::severity ||
                             span.kind == support_assist::LogHighlightKind::heading ||
                             span.kind == support_assist::LogHighlightKind::timestamp ||
                             span.kind == support_assist::LogHighlightKind::thread_id ||
                             span.kind == support_assist::LogHighlightKind::guid ||
                             span.kind == support_assist::LogHighlightKind::ip_address ||
                             span.kind == support_assist::LogHighlightKind::component ||
                             span.kind == support_assist::LogHighlightKind::stack_frame;
      if (!skimmable)
        continue;
    }

    COLORREF color = row_text;
    bool bold = false;
    bool italic = false;
    bool underline = false;
    switch (span.kind) {
    case support_assist::LogHighlightKind::timestamp:
      color = structural;
      break;
    case support_assist::LogHighlightKind::thread_id:
      // Following one thread down a log is a routine task and these logs interleave many. A stable
      // colour per thread makes a single thread traceable without filtering.
      color = identifier_color(raw_line.substr(span.start, length));
      break;
    case support_assist::LogHighlightKind::severity:
      // The one place the strong UDL colours are used outright. Bold, and pure, so the eye lands
      // on the severity token itself rather than on a coloured rectangle.
      color = analysis.severity == support_assist::LogLineSeverity::warning ? warn : error;
      bold = true;
      italic = analysis.severity != support_assist::LogLineSeverity::warning;
      break;
    case support_assist::LogHighlightKind::heading:
      // "Starting new log" and the ===== rules are fold boundaries in the UDL and are what an
      // engineer scrolls to when locating a session.
      color = banner;
      bold = true;
      break;
    case support_assist::LogHighlightKind::component:
      // The subsystem column (cli, alg, net, dsk, srv, stg, vim, objagent) gets a stable colour per
      // subsystem. A run of work handing off between subsystems is one of the most useful shapes in
      // a Veeam log, and in a single colour it is invisible.
      color = identifier_color(raw_line.substr(span.start, length));
      break;
    case support_assist::LogHighlightKind::metadata_label:
    case support_assist::LogHighlightKind::backup_concept:
      // Colour without weight. Bolding these turned every notable line into a run of heavy text
      // competing with the severity token that is supposed to be the anchor.
      color = metadata;
      break;
    case support_assist::LogHighlightKind::stack_frame:
      // ALWAYS subordinate, including on an error row.
      //
      // Measured on a real plug-in session log: of 12,456 Error lines, the top eight repeated
      // bodies are .NET frames such as "at Veeam.Backup.ProxyProvider.CProxyRawDeployerService
      // .TestConnection(...)" - 692 identical occurrences each. Painting those in the error colour
      // is what produces a red page, and it buries the line that actually matters, which in the
      // same log is "[wee-repo22] Failed to connect to Installer service". The frames are context
      // for that line, never a finding of their own.
      color = muted;
      italic = true;
      break;
    case support_assist::LogHighlightKind::success:
      color = success;
      break;
    case support_assist::LogHighlightKind::lifecycle:
      color = metadata;
      break;
    case support_assist::LogHighlightKind::url:
    case support_assist::LogHighlightKind::path:
      color = link;
      break;
    case support_assist::LogHighlightKind::guid:
      // One colour per distinct GUID, so the same session or object id is recognisable on sight
      // wherever it appears instead of being read digit by digit.
      color = identifier_color(raw_line.substr(span.start, length));
      break;
    case support_assist::LogHighlightKind::ip_address: {
      const std::wstring_view value = raw_line.substr(span.start, length);
      // A link-local address means DHCP never answered, which is a finding in itself.
      // Only the link-local case earns weight - that one is a finding (DHCP never answered).
      // Every other address gets a stable colour per address, so the same host keeps the same
      // colour through the file and a second host is visibly a second host.
      const bool link_local = value.starts_with(L"169.254.");
      color = link_local ? warn : identifier_color(value);
      bold = link_local;
      // Underlined on a notable line because this is the token the engineer copies out to go look
      // at another machine: "RPC function call failed ... Target machine: [10.200.201.20:6160]"
      // is only actionable once you can pick the endpoint out of the sentence at a glance.
      underline = notable_line;
      break;
    }
    }
    add_viewer_style(state, line_start, prefix_length + span.start, length, color, bold,
                     CLR_INVALID, italic, underline);
  }
}
void apply_viewer_style(HWND edit, const ViewerStyleRange& style) {
  SendMessageW(edit, EM_SETSEL, style.start, style.end);
  CHARFORMAT2W format{};
  format.cbSize = sizeof(format);
  format.dwMask = CFM_COLOR | CFM_BOLD | CFM_ITALIC | CFM_UNDERLINE;
  format.crTextColor = style.foreground;
  format.dwEffects = 0;
  if (style.bold)
    format.dwEffects |= CFE_BOLD;
  if (style.italic)
    format.dwEffects |= CFE_ITALIC;
  if (style.underline)
    format.dwEffects |= CFE_UNDERLINE;
  if (style.background != CLR_INVALID) {
    format.dwMask |= CFM_BACKCOLOR;
    format.crBackColor = style.background;
  }
  SendMessageW(edit, EM_SETCHARFORMAT, SCF_SELECTION, reinterpret_cast<LPARAM>(&format));
}

// --- Source viewer search -------------------------------------------------------------------
//
// A log viewer without a find box is not a log viewer. The engineer opens a 10 MB Job log to answer
// one question - where does "Failed to connect" first appear - and without search the only options
// are scrolling or giving up and grepping outside the product.
//
// Deliberately NOT a "highlight every match" implementation. Repainting thousands of character
// ranges on a multi-megabyte RichEdit stalls the UI, and restoring the semantic colours underneath
// afterwards means recomputing every overlapping span. Selecting the current match gives the same
// answer, stays instant on the largest bundles, and the native selection is what makes the hit
// visible.
constexpr int kViewerSearchBarHeight = 30;
// Reconstruct a health snapshot and an environment snapshot from a raw log collection. These sit
// in the high block rather than beside kEnvironmentLoadId, because 171-199 is the tail of the
// kExplorerSystemToolFirstId range and its length is decided at runtime by the tool list.
constexpr int kEnvironmentLoadCollectionId = 6110;
constexpr int kEnvironmentOpenSavedId = 6112;
constexpr int kEnvironmentOpenMenuId = 6114;
constexpr int kHealthOpenMenuId = 6115;
// Integrations master/detail action buttons.
constexpr int kIntegrationActionId = 6116;     // Run (configured) / Acquire (optional)
constexpr int kIntegrationSecondaryId = 6117;  // Open publisher (optional) / Edit (configured)
constexpr int kIntegrationRemoveId = 6118;     // Remove
constexpr int kIntegrationAddId = 6119;        // header: add a configured tool
constexpr int kIntegrationOpenFolderId = 6120; // header: open the tools folder
constexpr int kIntegrationRefreshId = 6121;    // header: re-detect
constexpr int kIntegrationDescId = 6122;       // editable description for a configured tool
constexpr int kIntegrationFileLocationId = 6123;  // open the tool's folder in File Explorer
constexpr int kRunGoId = 6123;                 // guided-run window: Run / Stop
constexpr int kRunCloseId = 6124;              // guided-run window: Close
constexpr int kRunCliId = 6137;                // guided-run window: CLI
constexpr int kRunPresetId = 6138;             // guided-run window: Preset
constexpr int kRunViewId = 6139;               // guided-run window: Full output / Result
// The guided-run window wears the quick tool windows' colours.
constexpr COLORREF kRunWindowColour = RGB(18, 30, 28);
constexpr COLORREF kRunFieldColour = RGB(22, 42, 44);
constexpr COLORREF kRunTextColour = RGB(225, 236, 231);
constexpr COLORREF kRunLabelColour = RGB(196, 214, 207);
constexpr UINT kRunSpeedProgressMessage = WM_APP + 71;  // guided-run window: storage test progress
constexpr UINT kRunSpeedDoneMessage = WM_APP + 72;      // guided-run window: storage test result
constexpr UINT_PTR kRunPollTimer = 0xA71;      // guided-run output poll
constexpr int kEditBrowseId = 6125;            // tool editor: browse for the program
constexpr int kEditSaveId = 6126;              // tool editor: save
constexpr int kEditCancelId = 6127;            // tool editor: cancel
constexpr int kQueryEditorRunId = 6147;        // SQL Tools query editor: Run query
constexpr int kQueryEditorCancelId = 6148;     // SQL Tools query editor: Cancel
constexpr int kDbConnectId = 6128;             // db console: Connect / Disconnect
constexpr int kDbSendId = 6129;                // db console: send the current query
constexpr int kDbSaveId = 6130;                // db console: save the transcript
constexpr int kDbInsertId = 6131;              // db console: insert the built query
constexpr int kDbScanId = 6132;                // db console: scan the live schema for tables
constexpr int kDbQbTableId = 6133;             // db console: table combo (drives column scan)
constexpr int kDbQbFilterColId = 6134;         // db console: filter-column combo (drives value scan)
constexpr int kDbServerId = 6135;              // db console: server combo (dropdown discovers SQL instances)
constexpr int kDbAuthId = 6136;                // db console: auth-mode combo (greys out user/password)
constexpr int kDbDatabaseId = 6146;            // db console: Database, listed after Connect
constexpr int kDbFindId = 6145;                // db console: Find instances on the typed host
constexpr UINT_PTR kDbPollTimer = 0xA72;       // db console output poll
// Commands inside the Open menu. Local to the menu, so they never collide with control ids.
constexpr UINT kOpenMenuSavedInCase = 1;
constexpr UINT kOpenMenuFile = 2;
constexpr UINT kOpenMenuCollection = 3;
constexpr UINT kOpenMenuArchive = 4;
// One command per imported machine, above every fixed entry so the two can never collide.
constexpr UINT kOpenMenuMachineFirst = 100;
