  const auto create_review_section = [&](HWND& label,
                                         HWND& list,
                                         int identifier,
                                         const wchar_t* heading,
                                         const std::array<std::pair<const wchar_t*, int>, 4>& columns) {
    label = CreateWindowExW(0, WC_STATICW, heading, WS_CHILD | SS_LEFT,
                            0, 0, 0, 0, window_, nullptr, instance_, nullptr);
    list = CreateWindowExW(0,
                           WC_LISTVIEWW,
                           nullptr,
                           WS_CHILD | WS_BORDER | LVS_REPORT | LVS_SHOWSELALWAYS,
                           0, 0, 0, 0, window_, control_id(identifier), instance_, nullptr);
    ListView_SetExtendedListViewStyle(list, LVS_EX_FULLROWSELECT | LVS_EX_DOUBLEBUFFER | LVS_EX_LABELTIP);
    ListView_SetBkColor(list, themed(RGB(13, 31, 33)));
    ListView_SetTextBkColor(list, themed(RGB(13, 31, 33)));
    ListView_SetTextColor(list, themed(RGB(225, 236, 231)));
    for (std::size_t column = 0; column < columns.size(); ++column) {
      LVCOLUMNW definition{};
      definition.mask = LVCF_TEXT | LVCF_WIDTH;
      definition.pszText = const_cast<LPWSTR>(columns[column].first);
      definition.cx = columns[column].second;
      ListView_InsertColumn(list, static_cast<int>(column), &definition);
    }
  };
