// Defined with draw_card below; declared here so open_card can hit-test the exact rectangle it paints.
static RECT integration_row_button_rect(const RECT& card_client);

void AppWindow::open_card(std::size_t index) {
  if (index >= cards_.size())
    return;
  const Card card = cards_[index];
  if (card.section_header)
    return;
  if (card.quick_tool) {
    open_quick_tool(*card.quick_tool);
    return;
  }
  if (card.destination == Page::storage_tools) {
    open_storage_tool(card.mode);
    return;
  }
  if (card.closes_application) {
    PostMessageW(window_, WM_CLOSE, 0, 0);
    return;
  }
  if (card.opens_page) {
    select_page(card.destination);
    return;
  }
  // Integrations catalogue: clicking a card's inline action button runs that row's primary action;
  // clicking anywhere else on the card selects its entry and fills the detail pane. The button
  // rectangle is derived from the SAME helper draw_card paints with, and hit-tested against the click
  // point (GetMessagePos is the position of the click that raised this BN_CLICKED). Keyboard
  // activation, whose cursor is elsewhere, falls through to selection - the detail-pane Run remains.
  if (page_ == Page::tool_manager && card.destination == Page::tool_manager) {
    if (card.mode >= 0 && card.mode < static_cast<int>(integration_entries_.size())) {
      integration_selected_ = card.mode;
      render_integration_detail();
      std::wstring row_label;
      bool row_enabled = false;
      if (integration_card_action(index, row_label, row_enabled) &&
          index < card_buttons_.size() && card_buttons_[index] != nullptr) {
        RECT client{};
        GetClientRect(card_buttons_[index], &client);
        const RECT button = integration_row_button_rect(card_full_rect(index, client));
        const DWORD packed = GetMessagePos();
        POINT point{GET_X_LPARAM(packed), GET_Y_LPARAM(packed)};
        ScreenToClient(card_buttons_[index], &point);
        if (PtInRect(&button, point) != FALSE && row_enabled) {
          // Process Monitor's button is Launch, the detail pane's second action, until a capture runs.
          const auto& entry = integration_entries_[static_cast<std::size_t>(card.mode)];
          integration_run_action(is_procmon_capture(entry) && entry.available && !integration_procmon_running() ? 1 : 0);
        }
      }
    }
    return;
  }
  // Dispatch these actions by the card's destination, independent of the page it is clicked from.
  // "Open This Case's Saved Review" appears on both Home and Log Review and carries destination Home
  // with mode 6; keying on the current page routed the Log Review copy into create_tool_session,
  // which opened Home's Toolbox overview.
  if (card.destination == Page::home && card.mode == 6) {
    resume_last_case_review();
    return;
  }
  if (card.destination == Page::home && card.mode == 3) {
    delete_active_case();
    return;
  }
  if (card.destination == Page::home && card.mode == 7) {
    toggle_workspace_role();
    return;
  }
  // Not gated on the current page: these cards moved from Home to Tools, and the action is the
  // same wherever it is invoked from.
  if (card.destination == Page::home && card.mode == 8) {
    prepare_last_execution_artifact();
    return;
  }
  if (card.destination == Page::home && card.mode == 9) {
    delete_last_execution_artifact();
    return;
  }
  create_tool_session(card);
}

// Whether the active case has a review already parsed and saved.
//
// Deliberately a file test, not a load: this is asked every time a page is built, and reading and
// deserialising an entire review model to decide whether to draw one button would cost more than
// the button saves. Both locations are checked because a case written by an older build kept the
// model beside case.json rather than under parsed/.
bool AppWindow::case_has_saved_review() const {
  const auto* workspace = active_case();
  if (workspace == nullptr)
    return false;
  std::error_code error;
  if (std::filesystem::is_regular_file(workspace->parsed / L"case-review-model.sat", error))
    return true;
  return std::filesystem::is_regular_file(workspace->root / L"case-review-model.sat", error);
}

std::vector<AppWindow::Card> AppWindow::cards_for_page(Page page) const {
  // A Tools category page: its cards with its section captions, the quick tools among them.
  if (const auto category = category_of_page(page))
    return tool_category_cards(*category);
  switch (page) {
  case Page::home:
    // Home is the status board (home_page.cpp): tiles that carry a state and open what is
    // behind it. The role switch is the header badge; Close is File > Exit.
    return {};
  case Page::case_manager:
  case Page::case_dashboard:
  case Page::environment_review:
  case Page::explorer:
  case Page::note_review:
  case Page::recent_activity:
  case Page::health_monitor:
    return {};
  case Page::tools: {
    // Every category's cards under its name, as the Tools page has always listed them; the
    // category tiles above them are the Tools board (home_page.cpp).
    std::vector<Card> cards;
    for (const auto category : listed_tool_categories()) {
      auto listed = tool_category_cards(category);
      if (listed.empty())
        continue;
      cards.push_back({L"", support_assist::wide_from_utf8_lossy(support_assist::ascii_upper(
                                std::string(support_assist::gui::tool_category_title(category)))),
                       L"", Page::tools, 0, false, false, true});
      for (Card& card : listed)
        cards.push_back(std::move(card));
    }
    return cards;
  }
  case Page::log_review: {
    std::vector<Card> cards;
    // What this case already holds, before the ways of producing more. Only when there is
    // something to open: a case is active AND it carries a parsed model.
    if (case_has_saved_review()) {
      cards.push_back({L"", L"SAVED REVIEW", L"", page, 0, false, false, true});
      cards.push_back({L"OPEN",
                       L"Open This Case's Saved Review",
                       L"Reopen the structured review already parsed into this case, without "
                       L"reading the raw logs again.",
                       Page::home,
                       6,
                       false});
      cards.push_back({L"", L"PARSE NEW EVIDENCE", L"", page, 0, false, false, true});
    }
    const std::vector<Card> parsers = {
        {L"AUTO",
         L"Auto Detect Veeam Logs (Recommended)",
         L"Discover the product/source profile for each supplied evidence source and review mixed-product bundles without assuming one global parser.",
         page,
         5,
         false},
        {L"FIND",
         L"Search Existing Logs",
         L"Search existing log files with copyable source path, line and matching text.",
         page,
         0,
         false},
        {L"VAW",
         L"Review Veeam Agent for Microsoft Windows Logs",
         L"Use the Veeam Agent for Microsoft Windows parser as an explicit source override.",
         page,
         1,
         false},
        {L"VBR",
         L"Review Veeam Backup & Replication Logs",
         L"Use the Veeam Backup & Replication parser as an explicit source override.",
         page,
         2,
         false},
        {L"SQL",
         L"Review Veeam Plug-In for Microsoft SQL Server Logs",
         L"Use the Microsoft SQL Server plug-in parser as an explicit source override.",
         page,
         3,
         false},
        {L"RMAN",
         L"Review Veeam Plug-In for Oracle RMAN Logs",
         L"Use the Oracle RMAN plug-in parser as an explicit source override.",
         page,
         4,
         false},
        {L"GENERIC",
         L"Generic Parser",
         L"For logs from several Veeam products, or from a product with no parser of its own.",
         page,
         6,
         false},
    };
    cards.insert(cards.end(), parsers.begin(), parsers.end());
    return cards;
  }
  case Page::tool_manager: {
    // Integrations catalogue: one card per optional tool and per configured tool. The card's mode
    // carries the catalogue index; clicking a card selects it and fills the detail pane rather than
    // running an operation. The header and detail buttons drive the actions.
    std::vector<Card> cards;
    bool seen_group = false;
    IntegrationEntry::Group current_group = IntegrationEntry::Group::your_tools;
    for (std::size_t index = 0; index < integration_entries_.size(); ++index) {
      const auto& entry = integration_entries_[index];
      if (!seen_group || entry.group != current_group) {
        current_group = entry.group;
        seen_group = true;
        Card header;
        header.title = entry.group == IntegrationEntry::Group::your_tools ? L"YOUR TOOLS"
                       : entry.group == IntegrationEntry::Group::launch    ? L"LAUNCH"
                       : entry.group == IntegrationEntry::Group::database  ? L"DATABASE"
                                                                           : L"ASSISTED";
        header.section_header = true;
        header.destination = Page::tool_manager;
        header.mode = -1;
        cards.push_back(std::move(header));
      }
      Card card;
      card.badge = entry.badge;
      card.title = entry.name;
      card.description = entry.subtitle;
      card.destination = Page::tool_manager;
      card.mode = static_cast<int>(index);
      card.status = entry.status;
      card.status_available = entry.available;
      cards.push_back(std::move(card));
    }
    if (cards.empty())
      cards.push_back({L"", L"No integrations found", L"Use Add to point SAT at a program.",
                       Page::tool_manager, -1, false});
    return cards;
  }
  case Page::diagnostics:
    return {
        {L"HOST",
         L"System Information",
         L"Review hostname, join state, BIOS UUID, hardware, OS and boot information.",
         page,
         1,
         false},
        {L"APPS",
         L"Products and Integrations",
         L"Detect installed Veeam products and approved optional support tools.",
         page,
         3,
         false},
        {L"SELF",
         L"SAT Self-Test",
         L"Check this copy of SAT: version and build, whether it can write to its temporary and case folders, and whether the bundled libraries still match their recorded SHA-256.",
         page,
         4,
         false},
    };
  case Page::help:
    // Dead: Help/About is no longer a navigable page. It was folded into the Help menu (Getting
    // Started, About SAT, Import Previous SAT Data) and F1 opens the current page's article in its
    // own window via help_mode_for_page(). This branch is unreachable and kept only until the
    // Page::help enum value and its rendering are removed in a later line.
    return {
        {L"ABOUT", L"About Support Assist Tool",
         L"Application identity, version, build revision, executable role and display recovery.",
         page, 14, false},
        {L"START", L"Getting Started",
         L"Workspace roles, navigation, sessions and the recommended support workflow. "
         L"Press F1 on any page for help about that page.",
         page, 0, false},
        {L"SAFE", L"Security, Elevation and Data",
         L"UAC and elevation, evidence handling, privacy, and customer-safe operation.",
         page, 12, false},
        {L"IMPORT", L"Import Previous SAT Data",
         L"Copy known SAT state from historical Logs/State layouts into ApplicationLogs without deleting the original files.",
         page, 15, false},
    };
  }
  return {};
}

// The cards of the pages behind the Tools categories, as each page has always listed them. The
// category pages add the quick tools and the Tools page lists them all (tool_category_cards).
std::vector<AppWindow::Card> AppWindow::category_base_cards(Page page) const {
  switch (page) {
  case Page::wmi_diagnostics:
    return {
        {L"WMI", L"WMI Health", L"This machine and its Windows, the WMI service and the services it needs, the repository's consistency and size, a timed probe of each namespace Veeam reads, and the WMI faults Windows logged recently.", page, kWmiHealthMode, false},
        {L"WMI", L"WMI Cluster Diagnostics", L"Query cluster-related WMI information using the built-in cluster preset.", page, 3, false},
        {L"WQL", L"Custom WMI Query", L"Run an engineer-supplied WQL query against the selected WMI namespace.", page, 4, false},
    };
  case Page::vbr_diagnostics:
    if (!local_vbr_server_available())
      return {};
    return {
        {L"JOBS", L"Running VBR Jobs", L"Review active VBR job sessions and send supported one-time stop requests through the local Veeam PowerShell module.", page, 23, false},
    };
  case Page::network_tools:
    return {
        {L"", L"CONNECTIVITY & PROTOCOLS", L"", page, 0, false, false, true},
        {L"NET", L"Remote Port Checker", L"Ports on another host: TCP or UDP over IPv4 and IPv6, where the name resolved from, source-interface routing and SAT-to-SAT verification.", page, 0, false},
        {L"TLS", L"TLS Handshake", L"Validate TLS negotiation, certificate presentation and protocol details independently of the application.", page, 18, false},
        {L"RPC", L"Windows RPC Connectivity", L"Validate TCP reachability and a DCE/RPC Endpoint Mapper exchange instead of treating TCP/135 alone as RPC success.", page, 20, false},
        {L"gRPC", L"gRPC Connectivity", L"Validate TCP, optional TLS/ALPN, HTTP/2 and gRPC transport behavior without requiring an application-specific service definition.", page, 21, false},
        {L"VEEAM", L"Veeam Service Channel", L"The channel Veeam's own processes use to reach their service: the service, its pipe, an HTTP/2 handshake and the gRPC lines the product logged.", page, support_assist::gui::kServiceChannelMode, false},
        {L"SMB", L"SMB Connectivity", L"Verify TCP/445, SMB negotiation, path access and a bounded write/read/delete payload outside Veeam.", page, 24, false},
        {L"", L"LISTENERS & PEER TESTS", L"", page, 0, false, false, true},
        {L"LISTEN", L"TCP / UDP Listener", L"Listen for controlled inbound TCP or UDP probes and record live peer/test details for correlation.", page, 1, false},
        {L"LOOP", L"Local Loopback Self-Test", L"Verify the local Windows TCP loopback stack using a temporary SAT listener only when the requested port is free.", page, 19, false},
        {L"gRPC", L"gRPC Listener", L"Run a cooperating SAT HTTP/2/gRPC transport listener for controlled two-endpoint case testing.", page, 22, false},
        {L"", L"CAPTURE & PERFORMANCE", L"", page, 0, false, false, true},
        {L"CAP", L"Packet Capture", L"Capture network evidence automatically into Log-Collections\\Tools\\Packet-Capture using pktmon or the Server 2016-compatible netsh fallback.", page, 5, false},
        {L"RATE", L"Network Throughput", L"Measure controlled TCP throughput between two toolkit endpoints using the built-in client/server or an approved iPerf copy.", page, 14, false},
    };
  case Page::guided_diagnostics: {
    std::vector<Card> result;
    const auto& available = support_assist::gui::guided_scenarios_here();
    for (std::size_t index = 0; index < available.size(); ++index) {
      result.push_back({L"GUIDE", wide(available[index].title), wide(available[index].symptom), page,
                        static_cast<int>(index), false});
    }
    if (result.empty()) {
      // A note rather than a tool: it opens this page, and the counts and Jump To leave it out.
      result.push_back({L"INFO", L"No Guided Diagnostics Detected",
                        L"No product-specific guided diagnostic is applicable to the Veeam roles detected on this host.",
                        page, 0, true});
    }
    return result;
  }
  case Page::log_collection:
    return {
        {L"AUTO",
         L"Universal Veeam Log Collection",
         L"Detect Veeam products on this machine, select what belongs to the case scope, and gather the appropriate bounded logs and support context.",
         page,
         0,
         false},
        {L"CUSTOM",
         L"Custom Paths",
         L"Collect explicitly selected customer-approved files or folders when catalog paths are not sufficient.",
         page,
         1,
         false},
    };
  case Page::sql_tools:
    return {
        {L"PERM", L"Permission check",
         L"An account's rights against Veeam's Permissions page: guest processing or the configuration database.",
         page, 0, false},
        {L"SHAPE", L"Server shape", L"Failover cluster instance, availability groups, replicas and backup preference.",
         page, 1, false},
        {L"LOG", L"Backups and log chain", L"Whose backups msdb holds, and gaps or breaks in the log chain.", page, 2,
         false},
        {L"FILES", L"Database files", L"Every database file and the volume it is on.", page, 3, false},
        {L"QUERY", L"Read-only query", L"A query that reads data, typed or chosen from the named queries.", page, 4, false},
    };
  case Page::vss_tools:
    return {
        {L"WRITER",
         L"Enumerate VSS Writers",
         L"List writer identities, states and last reported failures.",
         page,
         0,
         false},
        {L"TEST",
         L"Run VSS Test Job",
         L"Create, hold, complete and release an owned test snapshot set.",
         page,
         1,
         false},
    };
  case Page::filesystem_change:
    // System Differences: a card per type, each opening a page with that type's Capture, Compare and
    // Open (files 0, 1 and 4; the registry 2, 3 and 5).
    return {
        {L"FILES", L"File Differences",
         L"Capture a folder's files and folders, compare the capture with now or with a second capture, and open a "
         L"capture to see what it holds and the compares kept in it.",
         page, 0, false},
        {L"REG", L"Registry Differences",
         L"Capture a registry key or a whole hive, compare the capture with now or with a second capture, and open "
         L"a capture to see what it holds and the compares kept in it.",
         page, 2, false},
    };
  case Page::storage_tools: {
    // The Disk Speed Test is an integration: DiskSpd's Run on Integrations opens it.
    std::vector<Card> cards;
    if (object_storage_enabled())
      cards.push_back({L"S3", L"Object Storage Check",
                       L"Experimental. An S3-compatible bucket as Veeam reaches it: the endpoint, its certificate, the "
                       L"clock, the sign-in and the immutability settings. It writes nothing.",
                       page, 1, false});
    return cards;
  }
  default:
    return {};
  }
}

// The Disk Speed Test is DiskSpd's run window; DiskSpd comes from Integrations. The Object Storage
// Check is a task in the page's session tabs.
void AppWindow::open_storage_tool(int mode) {
  if (mode == 1) {
    open_object_storage_task();
    return;
  }
  rebuild_integration_catalogue();
  const auto found = std::find_if(integration_entries_.begin(), integration_entries_.end(),
                                  [](const IntegrationEntry& entry) { return entry.id == "diskspd"; });
  if (found != integration_entries_.end() && found->available) {
    open_run_window(*found);
    return;
  }
  if (MessageBoxW(window_,
                  L"The Disk Speed Test runs DiskSpd, Microsoft's storage load generator, which is not in "
                  L"SAT's tools folder. Open Integrations to get it?",
                  L"Disk Speed Test", MB_YESNO | MB_ICONINFORMATION) != IDYES)
    return;
  if (found != integration_entries_.end())
    integration_selected_ = static_cast<int>(found - integration_entries_.begin());
  select_page(Page::tool_manager);
}

void AppWindow::open_object_storage_task() {
  // One task at a time: an open one comes to the front.
  for (std::size_t index = 0; index < sessions_.size(); ++index) {
    if (sessions_[index] != nullptr && sessions_[index]->embedded_view != nullptr &&
        IsWindow(sessions_[index]->embedded_view) != FALSE) {
      activate_session(static_cast<int>(index));
      return;
    }
  }
  Card card{L"S3", L"Object Storage Check",
            L"Experimental. An S3-compatible bucket as Veeam reaches it: the endpoint, its certificate, the clock, the "
            L"sign-in, the immutability settings and the key's permissions. It writes nothing.",
            Page::storage_tools, 1, false};
  if (!create_tool_session(card))
    return;
  ToolSession* session = active_session();
  if (session == nullptr)
    return;
  session->embedded_view =
      open_quick_tool(support_assist::gui::ShortcutCommand::object_storage_check, std::wstring(), true);
  session->status = L"Choose the storage, type the bucket and press Check.";
  update_tool_tabs();
  update_control_visibility();
  RECT client{};
  GetClientRect(window_, &client);
  layout(client.right, client.bottom);
  commit_visual_state();
  if (session->embedded_view != nullptr) {
    if (HWND first = GetNextDlgTabItem(session->embedded_view, nullptr, FALSE))
      SetFocus(first);
  }
}

HWND AppWindow::task_view_containing(HWND control) const {
  if (control == nullptr)
    return nullptr;
  for (const auto& session : sessions_) {
    if (session != nullptr && session->embedded_view != nullptr &&
        (control == session->embedded_view || IsChild(session->embedded_view, control) != FALSE))
      return session->embedded_view;
  }
  return nullptr;
}

bool AppWindow::object_storage_enabled() const {
#ifdef SUPPORT_ASSIST_OBJECT_STORAGE_CHECK
  return read_setting(L"Experimental", L"ObjectStorageCheck", L"0") == L"1";
#else
  return false;
#endif
}

std::optional<AppWindow::Page> AppWindow::page_of_workspace(support_assist::gui::WorkspacePage page) {
  using support_assist::gui::WorkspacePage;
  switch (page) {
  case WorkspacePage::home: return Page::home;
  case WorkspacePage::case_manager: return Page::case_manager;
  case WorkspacePage::case_dashboard: return Page::case_dashboard;
  case WorkspacePage::environment_review: return Page::environment_review;
  case WorkspacePage::note_review: return Page::note_review;
  case WorkspacePage::recent_activity: return Page::recent_activity;
  case WorkspacePage::health_monitor: return Page::health_monitor;
  case WorkspacePage::tools: return Page::tools;
  case WorkspacePage::general_tools: return Page::general_tools;
  case WorkspacePage::storage_tools: return Page::storage_tools;
  case WorkspacePage::wmi_diagnostics: return Page::wmi_diagnostics;
  case WorkspacePage::vbr_diagnostics: return Page::vbr_diagnostics;
  case WorkspacePage::network_tools: return Page::network_tools;
  case WorkspacePage::guided_diagnostics: return Page::guided_diagnostics;
  case WorkspacePage::log_collection: return Page::log_collection;
  case WorkspacePage::log_review: return Page::log_review;
  case WorkspacePage::explorer: return Page::explorer;
  case WorkspacePage::remote: return Page::remote;
  case WorkspacePage::sql_tools: return Page::sql_tools;
  case WorkspacePage::vss_tools: return Page::vss_tools;
  case WorkspacePage::registry_change: return Page::registry_change;
  case WorkspacePage::filesystem_change: return Page::filesystem_change;
  case WorkspacePage::tool_manager: return Page::tool_manager;
  case WorkspacePage::diagnostics: return Page::diagnostics;
  case WorkspacePage::help: return std::nullopt;
  }
  return std::nullopt;
}

AppWindow::Page AppWindow::page_of_category(support_assist::gui::ToolCategory category) {
  return page_of_workspace(support_assist::gui::tool_category_page(category)).value_or(Page::tools);
}

std::optional<support_assist::gui::ToolCategory> AppWindow::category_of_page(Page page) {
  for (const auto& info : support_assist::gui::kToolCategoryTable) {
    if (info.sidebar && page_of_workspace(info.page) == page)
      return info.category;
  }
  return std::nullopt;
}

support_assist::gui::ToolCategory AppWindow::tool_card_category(const Card& card) {
  if (card.quick_tool)
    return support_assist::gui::quick_tool_category(*card.quick_tool);
  if (card.destination == Page::home)
    return support_assist::gui::ToolCategory::last_output;
  return category_of_page(card.destination).value_or(support_assist::gui::ToolCategory::host_diagnostics);
}

// The categories this machine lists: VBR Diagnostics with a local backup server, Last Tool Output
// once a tool has produced output.
std::vector<support_assist::gui::ToolCategory> AppWindow::listed_tool_categories() const {
  using support_assist::gui::ToolCategory;
  std::vector<ToolCategory> listed;
  for (const auto category : support_assist::gui::kToolCategories) {
    if (category == ToolCategory::vbr_diagnostics && !local_vbr_server_available())
      continue;
    if (category == ToolCategory::last_output && !last_execution_artifact_)
      continue;
    // A category without a sidebar row has its operations on another page (the registry's are on
    // System Differences).
    if (category != ToolCategory::last_output && !support_assist::gui::tool_category_info(category).sidebar)
      continue;
    // Storage Tools holds only the Object Storage Check, which Settings > General > Experimental adds.
    if (category == ToolCategory::storage_tools && !object_storage_enabled())
      continue;
    listed.push_back(category);
  }
  return listed;
}

// A category's cards with its section captions. The quick tools join Network Tools after the
// Remote Port Checker and open Host Diagnostics (gui_shared/home_board.hpp).
std::vector<AppWindow::Card> AppWindow::tool_category_cards(support_assist::gui::ToolCategory category) const {
  namespace board = support_assist::gui;
  const auto quick_cards = [&]() {
    std::vector<Card> found;
    for (const auto& quick : board::quick_tool_cards()) {
      if (board::quick_tool_category(quick.tool) != category)
        continue;
      Card card{wide(quick.badge), wide(quick.title), wide(quick.description), Page::tools, 0, false};
      card.quick_tool = quick.tool;
      found.push_back(std::move(card));
    }
    return found;
  };
  switch (category) {
  case board::ToolCategory::network_tools: {
    std::vector<Card> cards;
    for (Card& card : category_base_cards(Page::network_tools)) {
      const bool follow = !card.section_header && card.destination == Page::network_tools &&
                          card.mode == board::kNetworkQuickToolsFollowMode;
      cards.push_back(std::move(card));
      if (follow) {
        for (Card& quick : quick_cards())
          cards.push_back(std::move(quick));
      }
    }
    return cards;
  }
  case board::ToolCategory::host_diagnostics: {
    std::vector<Card> cards{{L"", wide(board::kQuickChecksSection), L"", Page::general_tools, 0, false, false, true}};
    for (Card& quick : quick_cards())
      cards.push_back(std::move(quick));
    cards.push_back({L"", L"HOST CHECKS", L"", Page::general_tools, 0, false, false, true});
    cards.push_back({L"CHECK", L"Host Checks",
                     L"Read-only checks of what most often explains a failed snapshot or backup: backup events, the "
                     L"Veeam drivers, VSS shadow storage, and the .NET and TLS settings.",
                     Page::general_tools, kHostChecksMode, false});
    cards.push_back({L"PROC", L"Process Inventory",
                     L"One row per running process on this machine: PID and parent, threads and working set, the "
                     L"executable path and the command line.",
                     Page::general_tools, 13, false});
    cards.push_back({L"PIPE", L"Named Pipes",
                     L"Every named pipe on this machine by name with its instance counts; Veeam's, SQL Server's and "
                     L"PostgreSQL's marked with their service. No pipe is opened.",
                     Page::general_tools, kNamedPipesMode, false});
    cards.push_back({L"", L"INSTALLED SOFTWARE", L"", Page::general_tools, 0, false, false, true});
    cards.push_back({L"MSI", L"Installer Cache Check",
                     L"The installed products by UpgradeCode or name, the cached package Windows keeps for each and "
                     L"whether it is there, and an installer or ISO folder checked against them.",
                     Page::general_tools, kInstallerCacheMode, false});
    return cards;
  }
  case board::ToolCategory::last_output: {
    if (!last_execution_artifact_)
      return {};
    const std::wstring output_tool = wide(last_execution_artifact_->tool_name);
    return {{L"EXPORT", L"Prepare " + output_tool + L" Output",
             L"Package the most recently completed " + output_tool +
                 L" diagnostic output with its hostname, manifest and SHA-256 hashes for "
                 L"transfer to the review workstation.",
             Page::home, 8, false},
            {L"CLEAN", L"Delete Last " + output_tool + L" Output",
             L"Permanently remove the most recently completed " + output_tool +
                 L" output after its required evidence has been transferred.",
             Page::home, 9, false}};
  }
  default:
    return category_base_cards(page_of_category(category));
  }
}

// Every tool card, flat: what the category tiles count and Jump To searches.
std::vector<AppWindow::Card> AppWindow::all_tool_cards() const {
  std::vector<Card> cards;
  for (const auto category : listed_tool_categories()) {
    for (Card& card : tool_category_cards(category)) {
      if (!card.section_header)
        cards.push_back(std::move(card));
    }
  }
  return cards;
}

bool AppWindow::card_catalog_scrolls() const noexcept {
  return page_ == Page::tools || page_ == Page::tool_manager || is_general_tools_child(page_);
}

bool AppWindow::shows_tools_board() const noexcept {
  return menu_view_ && (page_ == Page::tools || is_general_tools_child(page_));
}

void AppWindow::rebuild_cards() {
  cards_ = cards_for_page(page_);
  // A new page's cards wait for its layout to place them; until then none shows at the previous
  // page's positions.
  card_in_view_.assign(card_buttons_.size(), false);
  update_card_buttons();
}

// Whether a card shows: every card of the page, except on a scrolling card page, where only those
// the last layout placed in the view do. A card left out of the view keeps its last position, and
// shown there it would draw outside the view, over whatever is below.
bool AppWindow::card_shown(std::size_t index) const {
  if (!menu_view_ || index >= cards_.size())
    return false;
  if (!card_catalog_scrolls())
    return true;
  return index < card_in_view_.size() && card_in_view_[index];
}

void AppWindow::update_card_buttons() {
  for (std::size_t index = 0; index < card_buttons_.size(); ++index) {
    const bool used = index < cards_.size();
    if (used) {
      const std::wstring accessible_name = cards_[index].title + L". " + cards_[index].description;
      SetWindowTextW(card_buttons_[index], accessible_name.c_str());
      tooltip_texts_[card_buttons_[index]] = accessible_name;
    }
    ShowWindow(card_buttons_[index], card_shown(index) ? SW_SHOW : SW_HIDE);
    EnableWindow(card_buttons_[index], used && !cards_[index].section_header ? TRUE : FALSE);
  }
}

void AppWindow::update_control_visibility() {
  if (!(menu_view_ && card_catalog_scrolls()))
    ShowWindow(card_scrollbar_, SW_HIDE);
  for (std::size_t index = 0; index < card_buttons_.size(); ++index)
    ShowWindow(card_buttons_[index], card_shown(index) ? SW_SHOW : SW_HIDE);
  // Home's health is the board's health strip now; the older one-line block stays hidden.
  const bool show_health = false;
  ShowWindow(home_board_, menu_view_ && page_ == Page::home ? SW_SHOW : SW_HIDE);
  ShowWindow(tools_board_, shows_tools_board() ? SW_SHOW : SW_HIDE);
  ShowWindow(health_title_, show_health ? SW_SHOW : SW_HIDE);
  ShowWindow(health_summary_, show_health ? SW_SHOW : SW_HIDE);
  ShowWindow(health_toggle_, show_health ? SW_SHOW : SW_HIDE);
  ShowWindow(health_volumes_, show_health && !health_collapsed_ ? SW_SHOW : SW_HIDE);
  ShowWindow(health_note_, show_health && !health_collapsed_ ? SW_SHOW : SW_HIDE);
  ShowWindow(back_, (!menu_view_ || page_ != Page::home) ? SW_SHOW : SW_HIDE);

  const bool direct_page = !menu_view_ &&
                           (page_ == Page::case_manager ||
                            page_ == Page::case_dashboard ||
                            page_ == Page::environment_review ||
                            page_ == Page::explorer ||
                            page_ == Page::remote ||
                            page_ == Page::note_review ||
                            page_ == Page::recent_activity ||
                            page_ == Page::health_monitor ||
                            page_ == Page::diagnostics);
  const bool recent_activity_page = !menu_view_ && page_ == Page::recent_activity;
  ShowWindow(activity_load_, recent_activity_page ? SW_SHOW : SW_HIDE);
  ShowWindow(activity_board_, recent_activity_page ? SW_SHOW : SW_HIDE);
  const bool health_dashboard = !menu_view_ && page_ == Page::health_monitor;
  const bool case_dashboard = !menu_view_ && page_ == Page::case_dashboard;
  const bool case_manager_page = !menu_view_ && page_ == Page::case_manager;
  const bool environment_review = !menu_view_ && page_ == Page::environment_review;
  // The Remote page draws its own surface and has no operation results, output label or context
  // help. Without this the shared results grid stays where the previous page left it and paints
  // over the terminal - which is exactly how the Third Party table leaked onto it.
  const bool remote_page = !menu_view_ && page_ == Page::remote;
  const bool explorer_page = !menu_view_ && page_ == Page::explorer;
  const bool note_review_page = !menu_view_ && page_ == Page::note_review;
  const bool diagnostics_page = !menu_view_ && page_ == Page::diagnostics;
  for (HWND control : {diagnostics_report_, diagnostics_run_, diagnostics_copy_})
    ShowWindow(control, diagnostics_page ? SW_SHOW : SW_HIDE);
  const bool operation_page = !menu_view_ && !direct_page;
  for (HWND control : {mode_label_, mode_combo_, form_intro_, action_, cancel_})
    ShowWindow(control, operation_page ? SW_SHOW : SW_HIDE);
  // Only where a command line can be emitted in full. build_cli_command() returns empty for pages
  // whose CLI verbs do not yet cover every control, and an empty command must not offer a button.
  // Cached, not re-derived in layout(). Reading this back with IsWindowVisible() during layout
  // made positioning depend on whether visibility had already been applied this pass - the same
  // ordering trap that left the Recent Activity loader shown but never sized.
  // Shown on every operation page, including ones with no mapping yet. Hiding it where the CLI
  // does not reach made an unmapped tool and a missing feature look identical, so the builder read
  // as absent across most of the application. It is present everywhere and says plainly when a
  // tool has no command-line equivalent yet; the gaps are legible instead of silent.
  show_cli_available_ = operation_page;
  ShowWindow(show_cli_, show_cli_available_ ? SW_SHOW : SW_HIDE);
  if (!operation_page)
    open_output_available_ = false;
  ShowWindow(open_output_, open_output_available_ ? SW_SHOW : SW_HIDE);
  // The selector above the body is not always choosing an "Operation". On Help it chooses which
  // ARTICLE to read, and on tool pages it chooses which tool to run. Labelling every one of them
  // "Operation" made the Help page read as though an article were something to execute.
  if (operation_page) {
    const wchar_t* selector_label = category_of_page(page_) ? L"Tool" : L"Operation";
    switch (page_) {
    case Page::help: selector_label = L"Help article"; break;
    case Page::diagnostics: selector_label = L"Diagnostic"; break;
    case Page::tools:
    case Page::tool_manager: selector_label = L"Tool"; break;
    case Page::log_collection: selector_label = L"Collection profile"; break;
    case Page::log_review: selector_label = L"Review action"; break;
    default: break;
    }
    set_control_text(mode_label_, selector_label);
  }
  const bool differences_page = operation_page && page_ == Page::filesystem_change && !menu_view_;
  ShowWindow(differences_compare_, differences_page ? SW_SHOW : SW_HIDE);
  ShowWindow(differences_load_, differences_page ? SW_SHOW : SW_HIDE);
  ShowWindow(reset_output_, operation_page &&
                                (page_ == Page::general_tools || page_ == Page::wmi_diagnostics ||
                                 page_ == Page::vbr_diagnostics || page_ == Page::network_tools ||
                                 page_ == Page::guided_diagnostics)
                                ? SW_SHOW : SW_HIDE);
  const ToolSession* session = active_session();
  const bool help_detail = operation_page && session != nullptr && session->page == Page::help;
  // A task with a view of its own (the Object Storage Check) shows it in place of the form and results.
  const bool task_view = operation_page && session != nullptr && session->embedded_view != nullptr &&
                         session->page == page_;
  for (const auto& candidate : sessions_) {
    if (candidate != nullptr && candidate->embedded_view != nullptr)
      ShowWindow(candidate->embedded_view, task_view && candidate.get() == session ? SW_SHOW : SW_HIDE);
  }
  if (task_view) {
    for (HWND control : {mode_label_, mode_combo_, form_intro_, primary_label_, primary_edit_, primary_browse_,
                         secondary_label_, secondary_edit_, secondary_browse_, tertiary_label_, tertiary_edit_,
                         tertiary_browse_, quaternary_label_, quaternary_edit_, quaternary_browse_, quinary_label_,
                         quinary_edit_, quinary_browse_, senary_label_, senary_edit_, senary_browse_, option_check_,
                         mode_check_, action_, cancel_, reset_output_, show_cli_, tool_combo_})
      ShowWindow(control, SW_HIDE);
  }
  const bool review_dashboard = operation_page && session != nullptr &&
                                session->veeam_review != nullptr &&
                                session->page == Page::log_review && is_veeam_review_mode(session->mode);
  if (review_dashboard) {
    for (HWND control : {mode_label_, mode_combo_, form_intro_, primary_label_, primary_edit_,
                         primary_browse_, secondary_label_, secondary_edit_, secondary_browse_,
                         tertiary_label_, tertiary_edit_, tertiary_browse_, quaternary_label_,
                         quaternary_edit_, quaternary_browse_, quinary_label_, quinary_edit_,
                         quinary_browse_, senary_label_, senary_edit_, senary_browse_,
                         option_check_, mode_check_, context_help_})
      ShowWindow(control, SW_HIDE);
    ShowWindow(action_, SW_HIDE);
    ShowWindow(reset_output_, SW_HIDE);
    ShowWindow(review_state_banner_, SW_SHOW);
    ShowWindow(review_reanalyze_, SW_SHOW);
    ShowWindow(review_more_, SW_SHOW);
    ShowWindow(review_append_, SW_HIDE);
    ShowWindow(review_note_, SW_HIDE);
    ShowWindow(review_bookmark_, SW_HIDE);
    ShowWindow(cancel_, session->busy ? SW_SHOW : SW_HIDE);
  }
  // A task view and the review dashboard take the form's place, drop-downs included.
  if (task_view || review_dashboard) {
    for (std::size_t slot = 0; slot < slot_combos_.size(); ++slot) {
      ShowWindow(slot_combos_[slot], SW_HIDE);
      ShowWindow(slot_lists_[slot], SW_HIDE);
    }
  }
  if (!review_dashboard)
    ShowWindow(review_state_banner_, SW_HIDE);
  if (run_header_ != nullptr && (menu_view_ || run_header_text_.empty()))
    ShowWindow(run_header_, SW_HIDE);
  ShowWindow(output_label_, !menu_view_ && !health_dashboard && !case_dashboard && !environment_review && !explorer_page && !remote_page && !note_review_page && page_ != Page::case_manager && !task_view && !diagnostics_page ? SW_SHOW : SW_HIDE);
  // A Tools operation that has not run shows its hint card where its results will be.
  const bool operation_guide = operation_guide_wanted();
  ShowWindow(operation_guide_, operation_guide ? SW_SHOW : SW_HIDE);
  ShowWindow(results_, !menu_view_ && !health_dashboard && !case_dashboard && !environment_review &&
                           !explorer_page && !remote_page && !note_review_page && !help_detail && !cli_output_active_ && !task_view && !diagnostics_page && !operation_guide ? SW_SHOW : SW_HIDE);
  // The filter sits on the caption row above the table, wherever both are shown.
  ShowWindow(results_filter_,
             (GetWindowLongPtrW(output_label_, GWL_STYLE) & WS_VISIBLE) != 0 &&
                     (GetWindowLongPtrW(results_, GWL_STYLE) & WS_VISIBLE) != 0
                 ? SW_SHOW
                 : SW_HIDE);
  // Case Manager carries its own subtitle, as Case Dashboard and Environment Review do. Left
  // visible it is not merely redundant - the page does not lay it out, so it keeps whatever
  // position it had on the previous page and lands on top of the case table.
  ShowWindow(context_help_, !menu_view_ && !health_dashboard && !case_dashboard && !environment_review && !explorer_page && !remote_page && !note_review_page && !case_manager_page && !review_dashboard && !task_view && !diagnostics_page ? SW_SHOW : SW_HIDE);
  ShowWindow(detail_view_, SW_HIDE);
  for (HWND card : health_dashboard_cards_)
    ShowWindow(card, health_dashboard ? SW_SHOW : SW_HIDE);
  for (HWND control : {health_snapshot_banner_, health_load_snapshot_, health_live_snapshot_})
    ShowWindow(control, health_dashboard ? SW_SHOW : SW_HIDE);
  for (HWND control : {health_findings_label_, health_findings_, health_storage_label_,
                       health_storage_, health_network_label_, health_network_,
                       health_processes_label_, health_processes_, health_open_menu_,
                       health_filter_})
    ShowWindow(control, health_dashboard ? SW_SHOW : SW_HIDE);
  for (HWND control : {health_load_snapshot_, health_load_collection_, health_open_saved_})
    ShowWindow(control, SW_HIDE);
  EnableWindow(health_open_saved_,
               saved_collection_evidence_available(/*for_health=*/true) ? TRUE : FALSE);
  EnableWindow(health_live_snapshot_, saved_health_snapshot_loaded_ ? TRUE : FALSE);
  set_control_text(health_live_snapshot_, execution_host_enabled() ? L"Return to live" : L"Close snapshot");
  for (HWND control : {environment_heading_, environment_subtitle_, environment_text_,
                       environment_topology_, environment_refresh_,
                       environment_open_menu_})
    ShowWindow(control, environment_review ? SW_SHOW : SW_HIDE);
  // Superseded by the Open menu. Kept as controls so their handlers and every list that names them
  // stay valid, but never shown - a hidden control cannot be clicked and cannot go stale.
  for (HWND control : {environment_load_, environment_load_collection_, environment_open_saved_,
                       environment_pdf_})
    ShowWindow(control, SW_HIDE);
  // Greyed when the case has nothing saved. A button that looks available and then says "nothing
  // here" teaches an engineer not to trust the page.
  EnableWindow(environment_open_saved_,
               saved_collection_evidence_available(/*for_health=*/false) ? TRUE : FALSE);
  // The detail pane and its grid are alternatives chosen by present_environment_detail(). Leaving
  // the page hides both; entering it shows the text pane until a section is selected.
  if (!environment_review) {
    ShowWindow(environment_details_, SW_HIDE);
    ShowWindow(environment_detail_grid_, SW_HIDE);
  } else if (IsWindowVisible(environment_detail_grid_) == FALSE) {
    ShowWindow(environment_details_, SW_SHOW);
  }
  ShowWindow(environment_filter_,
             environment_review &&
                     (GetWindowLongPtrW(environment_detail_grid_, GWL_STYLE) & WS_VISIBLE) != 0
                 ? SW_SHOW
                 : SW_HIDE);
  for (HWND card : environment_cards_)
    ShowWindow(card, environment_review ? SW_SHOW : SW_HIDE);
  for (HWND control : {explorer_heading_, explorer_subtitle_, explorer_tabs_})
    ShowWindow(control, explorer_page ? SW_SHOW : SW_HIDE);
  // refresh_explorer_tab_visibility() derives every tab flag from `page_ == Page::explorer`, so it
  // already hides the entire Explorer surface when another page is active. Call it unconditionally.
  //
  // This previously ran only on the Explorer page, with a hand-maintained duplicate hide list in an
  // else branch. That duplicate drifted: it omitted the six dual-pane transfer controls and the
  // three Remote Console shell controls. Opening Explorer, selecting SSH/SFTP or a remote tab,
  // then navigating Home left "LOCAL FILES - <host>", its path box, Go/Refresh and the file list
  // painted over the Home cards; the Remote Console tab leaked its shell selector the same way.
  // One source of truth removes the drift entirely.
  refresh_explorer_tab_visibility();
  for (HWND control : {note_review_heading_, note_review_status_, note_review_scope_label_,
                       note_review_scope_combo_, note_review_text_, note_review_refresh_,
                       note_review_copy_, note_review_save_})
    ShowWindow(control, note_review_page ? SW_SHOW : SW_HIDE);
  for (HWND card : case_dashboard_cards_)
    ShowWindow(card, case_dashboard ? SW_SHOW : SW_HIDE);
  for (HWND control : {case_dashboard_heading_, case_dashboard_subtitle_, case_machine_label_,
                       case_machine_combo_, case_run_label_, case_run_combo_, case_session_label_,
                       case_session_combo_, case_copy_settings_, case_machine_summary_label_, case_machine_summary_,
                       case_review_summary_label_, case_review_summary_, case_evidence_summary_label_,
                       case_evidence_summary_, case_new_, case_load_review_,
                       case_append_logs_, case_notes_button_, case_tool_evidence_, case_more_})
    ShowWindow(control, case_dashboard ? SW_SHOW : SW_HIDE);
  for (HWND control : {case_reanalyze_, case_open_folder_, case_pdf_selected_, case_pdf_master_})
    ShowWindow(control, SW_HIDE);

  for (HWND control : {case_manager_heading_, case_manager_subtitle_, case_manager_new_,
                       case_manager_register_, case_manager_open_,
                       case_manager_delete_button_, case_manager_refresh_})
    ShowWindow(control, case_manager_page ? SW_SHOW : SW_HIDE);
  // Moved to the Case Dashboard. Kept as controls so their handlers and the lists that name them
  // stay valid, but never shown.
  for (HWND control : {case_manager_note_, case_manager_pdf_, case_manager_folder_})
    ShowWindow(control, SW_HIDE);
  for (HWND card : case_manager_cards_)
    ShowWindow(card, case_manager_page ? SW_SHOW : SW_HIDE);

  // Editor and form are alternatives: exactly one of them is on screen at a time.
  const bool case_editor = case_manager_page && !case_manager_form_open_;
  const bool case_form = case_manager_page && case_manager_form_open_;
  for (HWND control : {case_manager_status_label_, case_manager_status_combo_,
                       case_manager_next_label_, case_manager_next_edit_,
                       case_manager_notes_label_, case_manager_notes_edit_, case_manager_save_,
                       case_manager_summary_label_, case_manager_summary_})
    ShowWindow(control, case_editor ? SW_SHOW : SW_HIDE);
  for (HWND control : {case_manager_form_parent_label_, case_manager_form_parent_edit_,
                       case_manager_form_browse_, case_manager_form_id_label_,
                       case_manager_form_id_edit_, case_manager_form_title_label_,
                       case_manager_form_title_edit_, case_manager_form_engineer_label_,
                       case_manager_form_engineer_edit_, case_manager_form_folders_,
                       case_manager_form_create_, case_manager_form_cancel_})
    ShowWindow(control, case_form ? SW_SHOW : SW_HIDE);
  if (case_manager_page)
    update_case_manager_buttons();

  if (menu_view_ || direct_page) {
    for (HWND control : {primary_label_,
                         primary_edit_,
                         tool_combo_,
                         primary_browse_,
                         secondary_label_,
                         secondary_edit_,
                         secondary_browse_,
                         tertiary_label_,
                         tertiary_edit_,
                         tertiary_browse_,
                         quaternary_label_,
                         quaternary_edit_,
                         quaternary_browse_,
                         quinary_label_,
                         quinary_edit_,
                         quinary_browse_,
                         senary_label_,
                         senary_edit_,
                         senary_browse_,
                         option_check_,
                         mode_check_,
                         collection_products_label_,
                         network_interfaces_label_,
                         network_ipv4_check_,
                         network_ipv6_check_}) {
      ShowWindow(control, SW_HIDE);
    }
    for (HWND control : collection_product_checks_)
      ShowWindow(control, SW_HIDE);
    for (HWND control : network_interface_checks_)
      ShowWindow(control, SW_HIDE);
    // The fields' drop-downs go with the form; left shown they lie over the card wall.
    for (std::size_t slot = 0; slot < slot_combos_.size(); ++slot) {
      ShowWindow(slot_combos_[slot], SW_HIDE);
      ShowWindow(slot_lists_[slot], SW_HIDE);
    }
  }
  const bool show_review_filters = review_dashboard;
  for (HWND control : {review_machine_label_, review_machine_combo_,
                       review_job_filter_label_, review_job_filter_combo_,
                       review_run_label_, review_run_combo_})
    ShowWindow(control, show_review_filters ? SW_SHOW : SW_HIDE);
  // A folded Tools table shows its selected row in full under it.
  const bool folded_table = tools_form_folded();
  ShowWindow(detail_view_,
             (show_review_filters || help_detail || cli_output_active_ || folded_table) &&
                     !operation_guide
                 ? SW_SHOW
                 : SW_HIDE);
  // Integrations master/detail controls: the detail pane and header buttons follow the page; the
  // action buttons follow the selection (render_integration_detail decides those).
  const bool integrations_page = page_ == Page::tool_manager;
  for (HWND control : {integration_detail_, integration_add_, integration_open_folder_,
                       integration_refresh_})
    ShowWindow(control, integrations_page ? SW_SHOW : SW_HIDE);
  if (integrations_page) {
    render_integration_detail();
  } else {
    for (HWND control : {integration_action_, integration_secondary_, integration_remove_,
                         integration_file_location_, integration_desc_edit_, integration_desc_label_})
      ShowWindow(control, SW_HIDE);
  }
  for (HWND card : review_dashboard_cards_)
    ShowWindow(card, review_dashboard ? SW_SHOW : SW_HIDE);
  for (HWND control : {review_identity_label_, review_identity_, review_job_label_, review_job_,
                       review_components_label_, review_components_, review_reanalyze_, review_more_})
    ShowWindow(control, review_dashboard ? SW_SHOW : SW_HIDE);
  for (HWND control : {review_note_, review_bookmark_, review_append_})
    ShowWindow(control, SW_HIDE);
  const bool running = operation_page && session != nullptr && session->busy;
  ShowWindow(progress_, running ? SW_SHOW : SW_HIDE);
  ShowWindow(elapsed_, running ? SW_SHOW : SW_HIDE);
  update_session_controls();
}

// The inline action button on an Integrations catalogue card: a fixed-size pill at the far right of
// the card, past the availability status. draw_card paints it and open_card hit-tests it, so both
// derive its rectangle from the SAME card client rectangle here rather than each guessing.
static RECT integration_row_button_rect(const RECT& card_client) {
  const int width = 78;
  const int height = 26;
  const int margin = 16;
  const int top = card_client.top + ((card_client.bottom - card_client.top) - height) / 2;
  return RECT{card_client.right - margin - width, top, card_client.right - margin, top + height};
}

bool AppWindow::integration_card_action(std::size_t card_index, std::wstring& label,
                                        bool& enabled) const {
  if (page_ != Page::tool_manager || card_index >= cards_.size())
    return false;
  const int mode = cards_[card_index].mode;
  if (mode < 0 || mode >= static_cast<int>(integration_entries_.size()))
    return false;
  const auto& entry = integration_entries_[static_cast<std::size_t>(mode)];
  if (entry.kind == IntegrationEntry::Kind::configured_tool) {
    label = L"Run";
    enabled = entry.available;  // a configured tool whose program is gone cannot be run
    return true;
  }
  if (entry.database_console) {
    // A DB client: open its interactive console when present, otherwise acquire/get it.
    enabled = true;
    label = entry.available ? L"Open console"
            : entry.automatic_download ? L"Acquire"
                                       : L"Get";
    return true;
  }
  if (entry.built_in) {
    // An in-box tool with a guided run (Packet Monitor capture) still gets a Run action; otherwise
    // there is nothing to acquire, update or run from here.
    if (support_assist::gui::find_tool_run_profile(entry.id) != nullptr) {
      enabled = true;
      label = L"Run";
      return true;
    }
    return false;
  }
  enabled = true;
  if (is_procmon_capture(entry) && entry.available) {
    // Process Monitor opens with Launch, as Wireshark does; Stop while a capture runs. Its capture
    // starts from the detail pane.
    label = integration_procmon_running() ? L"Stop" : L"Launch";
    return true;
  }
  if (entry.managed_run && entry.available) {
    // A tool SAT runs itself (VSS Trace): Run starts the trace, and flips to Stop while it runs.
    label = (integration_run_active_id_ == entry.id) ? L"Stop" : L"Run";
    return true;
  }
  if (entry.available && support_assist::gui::find_tool_run_profile(entry.id) != nullptr) {
    label = L"Run";  // a guided command-line run (iPerf3 / SQLCMD / ETL2PCAPNG)
    return true;
  }
  if (entry.launches_gui && entry.available) {
    label = L"Launch";  // a full GUI tool (Process Monitor, Wireshark): open it
    return true;
  }
  if (entry.automatic_download)
    label = entry.available ? L"Update" : L"Acquire";  // SAT can fetch it directly
  else
    label = L"Get";  // SAT cannot fetch it; the action opens the official page
  return true;
}

// A card's whole rectangle in its own client coordinates: at the edge of a scrolled view its window
// holds only the part in view, and the rest lies above or below the client area, clipped.
RECT AppWindow::card_full_rect(std::size_t index, RECT client) const {
  if (index < card_full_height_.size() && card_full_height_[index] > 0) {
    client.top -= card_hidden_top_[index];
    client.bottom = client.top + card_full_height_[index];
  }
  return client;
}

void AppWindow::draw_card(const DRAWITEMSTRUCT& draw) const {
  const std::size_t index = static_cast<std::size_t>(draw.CtlID - kCardFirstId);
  if (index >= cards_.size())
    return;
  RECT rectangle = card_full_rect(index, draw.rcItem);
  if (cards_[index].section_header) {
    FillRect(draw.hDC, &rectangle, background_brush_);
    RECT text_rect{rectangle.left + 2, rectangle.top + 4, rectangle.right - 2, rectangle.bottom - 4};
    SetBkMode(draw.hDC, TRANSPARENT);
    SetTextColor(draw.hDC, themed(RGB(114, 224, 106)));
    const HGDIOBJ old_font = SelectObject(draw.hDC, heading_font_);
    DrawTextW(draw.hDC, cards_[index].title.c_str(), -1, &text_rect,
              DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS | DT_NOPREFIX);
    HPEN line = CreatePen(PS_SOLID, 1, themed(RGB(43, 86, 78)));
    if (line != nullptr) {
      const HGDIOBJ old_pen = SelectObject(draw.hDC, line);
      MoveToEx(draw.hDC, rectangle.left, rectangle.bottom - 2, nullptr);
      LineTo(draw.hDC, rectangle.right, rectangle.bottom - 2);
      SelectObject(draw.hDC, old_pen);
      DeleteObject(line);
    }
    SelectObject(draw.hDC, old_font);
    return;
  }
  // A card's mode is its entry's index; the group headers between the cards shift the card's own.
  const bool selected_row = page_ == Page::tool_manager && cards_[index].mode >= 0 &&
                            cards_[index].mode == integration_selected_;
  const bool pressed = (draw.itemState & ODS_SELECTED) != 0;
  const bool focused = (draw.itemState & ODS_FOCUS) != 0 || selected_row;
  HBRUSH fill = CreateSolidBrush((pressed || selected_row) ? themed(RGB(29, 72, 64)) : themed(RGB(18, 48, 49)));
  HPEN border = CreatePen(PS_SOLID,
                          focused ? 2 : 1,
                          focused ? themed(RGB(101, 215, 98)) : themed(RGB(43, 86, 78)));
  const HGDIOBJ old_brush = SelectObject(draw.hDC, fill);
  const HGDIOBJ old_pen = SelectObject(draw.hDC, border);
  RoundRect(draw.hDC,
            rectangle.left + 1,
            rectangle.top + 1,
            rectangle.right - 1,
            rectangle.bottom - 1,
            10,
            10);

  RECT badge{rectangle.left + 12, rectangle.top + 15, rectangle.left + 60, rectangle.bottom - 15};
  const HGDIOBJ old_font = SelectObject(draw.hDC, small_font_);
  HICON badge_icon = nullptr;
  if (page_ == Page::tool_manager && cards_[index].mode >= 0 &&
      cards_[index].mode < static_cast<int>(integration_entries_.size()))
    badge_icon = integration_entries_[static_cast<std::size_t>(cards_[index].mode)].icon;
  if (badge_icon != nullptr) {
    // A configured tool shows its program's own icon in place of a generated badge.
    const int icon_size = 32;
    const int icon_x = badge.left + ((badge.right - badge.left) - icon_size) / 2;
    const int icon_y = badge.top + ((badge.bottom - badge.top) - icon_size) / 2;
    DrawIconEx(draw.hDC, icon_x, icon_y, badge_icon, icon_size, icon_size, 0, nullptr, DI_NORMAL);
  } else {
    // A muted badge square with a subtle border, not a bright accent block, so a row without an app
    // icon stays inside the card's colour family instead of shouting.
    HBRUSH badge_fill = CreateSolidBrush(themed(RGB(26, 58, 50)));
    HPEN badge_pen = CreatePen(PS_SOLID, 1, themed(RGB(43, 86, 78)));
    const HGDIOBJ prev_badge_brush = SelectObject(draw.hDC, badge_fill);
    const HGDIOBJ prev_badge_pen = SelectObject(draw.hDC, badge_pen);
    RoundRect(draw.hDC, badge.left, badge.top, badge.right, badge.bottom, 9, 9);
    SetBkMode(draw.hDC, TRANSPARENT);
    SetTextColor(draw.hDC, themed(RGB(140, 205, 175)));
    DrawTextW(draw.hDC,
              cards_[index].badge.c_str(),
              -1,
              &badge,
              DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS | DT_NOPREFIX);
    SelectObject(draw.hDC, prev_badge_brush);
    SelectObject(draw.hDC, prev_badge_pen);
    DeleteObject(badge_fill);
    DeleteObject(badge_pen);
  }

  std::wstring row_action_label;
  bool row_action_enabled = false;
  const bool has_row_action = integration_card_action(index, row_action_label, row_action_enabled);
  const int right_reserve =
      cards_[index].status.empty() ? 28 : (has_row_action ? 210 : 132);
  RECT title_rect{
      rectangle.left + 72, rectangle.top + 11, rectangle.right - right_reserve, rectangle.top + 38};
  SelectObject(draw.hDC, card_font_);
  SetTextColor(draw.hDC, themed(RGB(244, 249, 246)));
  DrawTextW(draw.hDC,
            cards_[index].title.c_str(),
            -1,
            &title_rect,
            DT_LEFT | DT_VCENTER | DT_SINGLELINE | DT_END_ELLIPSIS | DT_NOPREFIX);
  RECT description_rect{
      rectangle.left + 72, rectangle.top + 39, rectangle.right - right_reserve, rectangle.bottom - 8};
  SelectObject(draw.hDC, small_font_);
  SetTextColor(draw.hDC, themed(RGB(176, 196, 188)));
  // Whole lines only (DT_EDITCONTROL), the last one ending in an ellipsis when the description is
  // longer than the card.
  DrawTextW(draw.hDC,
            cards_[index].description.c_str(),
            -1,
            &description_rect,
            DT_LEFT | DT_TOP | DT_WORDBREAK | DT_EDITCONTROL | DT_END_ELLIPSIS | DT_NOPREFIX);
  if (!cards_[index].status.empty()) {
    // Integrations catalogue: an availability pill on the right instead of the navigate arrow, and -
    // when the card has one - an inline action button ("Run" a configured tool, "Acquire"/"Update"
    // an optional one) at the very right, past the pill. The action sits to the right of the
    // Available / Not present message.
    int status_right = rectangle.right - 16;
    if (has_row_action) {
      // Drawn to match SAT's themed push buttons (dark face, hairline border, light label) rather
      // than a bright fill, so the row's action reads as a button in the same family as Add / Refresh.
      const RECT button = integration_row_button_rect(rectangle);
      HBRUSH button_fill = CreateSolidBrush(row_action_enabled ? themed(RGB(20, 49, 47)) : themed(RGB(17, 33, 34)));
      HPEN button_pen =
          CreatePen(PS_SOLID, 1, row_action_enabled ? themed(RGB(74, 105, 99)) : themed(RGB(48, 66, 64)));
      const HGDIOBJ prev_btn_brush = SelectObject(draw.hDC, button_fill);
      const HGDIOBJ prev_btn_pen = SelectObject(draw.hDC, button_pen);
      RoundRect(draw.hDC, button.left, button.top, button.right, button.bottom, 8, 8);
      SelectObject(draw.hDC, small_font_);
      SetBkMode(draw.hDC, TRANSPARENT);
      SetTextColor(draw.hDC, row_action_enabled ? themed(RGB(223, 235, 229)) : themed(RGB(132, 151, 144)));
      RECT button_label = button;
      DrawTextW(draw.hDC, row_action_label.c_str(), -1, &button_label,
                DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX);
      SelectObject(draw.hDC, prev_btn_brush);
      SelectObject(draw.hDC, prev_btn_pen);
      DeleteObject(button_fill);
      DeleteObject(button_pen);
      status_right = button.left - 10;
    }
    SelectObject(draw.hDC, small_font_);
    SIZE size{};
    GetTextExtentPoint32W(draw.hDC, cards_[index].status.c_str(),
                          static_cast<int>(cards_[index].status.size()), &size);
    const int pill_h = 22;
    const int pill_w = size.cx + 22;
    const int pill_top = rectangle.top + (rectangle.bottom - rectangle.top - pill_h) / 2;
    RECT pill{status_right - pill_w, pill_top, status_right, pill_top + pill_h};
    HBRUSH pill_fill =
        CreateSolidBrush(cards_[index].status_available ? themed(RGB(34, 78, 58)) : themed(RGB(78, 62, 30)));
    SelectObject(draw.hDC, pill_fill);
    SelectObject(draw.hDC, GetStockObject(NULL_PEN));
    RoundRect(draw.hDC, pill.left, pill.top, pill.right, pill.bottom, pill_h / 2, pill_h / 2);
    SetTextColor(draw.hDC, cards_[index].status_available ? themed(RGB(150, 226, 178)) : themed(RGB(228, 196, 138)));
    DrawTextW(draw.hDC, cards_[index].status.c_str(), -1, &pill,
              DT_CENTER | DT_VCENTER | DT_SINGLELINE | DT_NOPREFIX);
    DeleteObject(pill_fill);
  } else {
    RECT arrow{rectangle.right - 25, rectangle.top, rectangle.right - 5, rectangle.bottom};
    SelectObject(draw.hDC, heading_font_);
    SetTextColor(draw.hDC, themed(RGB(116, 218, 112)));
    DrawTextW(draw.hDC, L">", -1, &arrow, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
  }

  SelectObject(draw.hDC, old_font);
  SelectObject(draw.hDC, old_brush);
  SelectObject(draw.hDC, old_pen);
  DeleteObject(fill);
  DeleteObject(border);
}

